export const SOLUTIONS = {"14-1":{"ch":14,"entry":"alien_invasion.py","mode":"run","reason":null,"files":{"alien.py":"import pygame\n\nfrom pygame.sprite import Sprite\n\n\nclass Alien(Sprite):\n    \"\"\"A class to represent a single alien in the fleet.\"\"\"\n\n    def __init__(self, ai_game):\n        \"\"\"Initialize the alien and set its starting position.\"\"\"\n        super().__init__()\n        self.screen = ai_game.screen\n        self.settings = ai_game.settings\n\n        # Load the alien image and set its rect attribute.\n        self.image = pygame.image.load('images/alien.bmp')\n        self.rect = self.image.get_rect()\n\n        # Start each new alien near the top left of the screen.\n        self.rect.x = self.rect.width\n        self.rect.y = self.rect.height\n\n        # Store the alien's exact horizontal position.\n        self.x = float(self.rect.x)\n\n    def check_edges(self):\n        \"\"\"Return True if alien is at edge of screen.\"\"\"\n        screen_rect = self.screen.get_rect()\n        return (self.rect.right >= screen_rect.right) or (self.rect.left <= 0)\n\n    def update(self):\n        \"\"\"Move the alien right or left.\"\"\"\n        self.x += self.settings.alien_speed * self.settings.fleet_direction\n        self.rect.x = self.x","alien_invasion.py":"import sys\nfrom time import sleep\n\nimport pygame\n\nfrom settings import Settings\nfrom game_stats import GameStats\nfrom button import Button\nfrom ship import Ship\nfrom bullet import Bullet\nfrom alien import Alien\n\n\nclass AlienInvasion:\n    \"\"\"Overall class to manage game assets and behavior.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game, and create game resources.\"\"\"\n        pygame.init()\n        self.clock = pygame.time.Clock()\n        self.settings = Settings()\n\n        self.screen = pygame.display.set_mode(\n            (self.settings.screen_width, self.settings.screen_height))\n        pygame.display.set_caption(\"Alien Invasion\")\n\n        # Create an instance to store game statistics.\n        self.stats = GameStats(self)\n\n        self.ship = Ship(self)\n        self.bullets = pygame.sprite.Group()\n        self.aliens = pygame.sprite.Group()\n\n        self._create_fleet()\n\n        # Start Alien Invasion in an inactive state.\n        self.game_active = False\n\n        # Make the Play button.\n        self.play_button = Button(self, \"Play\")\n\n    def run_game(self):\n        \"\"\"Start the main loop for the game.\"\"\"\n        while True:\n            self._check_events()\n            \n            if self.game_active:\n                self.ship.update()\n                self._update_bullets()\n                self._update_aliens()\n\n            self._update_screen()\n            self.clock.tick(60)\n\n    def _check_events(self):\n        \"\"\"Respond to keypresses and mouse events.\"\"\"\n        for event in pygame.event.get():\n            if event.type == pygame.QUIT:\n                sys.exit()\n            elif event.type == pygame.KEYDOWN:\n                self._check_keydown_events(event)\n            elif event.type == pygame.KEYUP:\n                self._check_keyup_events(event)\n            elif event.type == pygame.MOUSEBUTTONDOWN:\n                mouse_pos = pygame.mouse.get_pos()\n                self._check_play_button(mouse_pos)\n\n    def _check_play_button(self, mouse_pos):\n        \"\"\"Start a new game when the player clicks Play.\"\"\"\n        button_clicked = self.play_button.rect.collidepoint(mouse_pos)\n        if button_clicked and not self.game_active:\n            self._start_game()\n\n    def _start_game(self):\n        \"\"\"Start a new game.\"\"\"\n        # Reset the game statistics.\n        self.stats.reset_stats()\n        self.game_active = True\n\n        # Get rid of any remaining bullets and aliens.\n        self.bullets.empty()\n        self.aliens.empty()\n\n        # Create a new fleet and center the ship.\n        self._create_fleet()\n        self.ship.center_ship()\n\n        # Hide the mouse cursor.\n        pygame.mouse.set_visible(False)\n\n\n    def _check_keydown_events(self, event):\n        \"\"\"Respond to keypresses.\"\"\"\n        if event.key == pygame.K_RIGHT:\n            self.ship.moving_right = True\n        elif event.key == pygame.K_LEFT:\n            self.ship.moving_left = True\n        elif event.key == pygame.K_q:\n            sys.exit()\n        elif event.key == pygame.K_SPACE:\n            self._fire_bullet() \n        elif (event.key == pygame.K_p) and (not self.game_active):\n            # Don't start a new game during an active game, that's probably\n            #   an accidental keypress.\n            self._start_game()           \n\n    def _check_keyup_events(self, event):\n        \"\"\"Respond to key releases.\"\"\"\n        if event.key == pygame.K_RIGHT:\n            self.ship.moving_right = False\n        elif event.key == pygame.K_LEFT:\n            self.ship.moving_left = False\n\n    def _fire_bullet(self):\n        \"\"\"Create a new bullet and add it to the bullets group.\"\"\"\n        if len(self.bullets) < self.settings.bullets_allowed:\n            new_bullet = Bullet(self)\n            self.bullets.add(new_bullet)\n\n    def _update_bullets(self):\n        \"\"\"Update position of bullets and get rid of old bullets.\"\"\"\n        # Update bullet positions.\n        self.bullets.update()\n\n        # Get rid of bullets that have disappeared.\n        for bullet in self.bullets.copy():\n            if bullet.rect.bottom <= 0:\n                self.bullets.remove(bullet)\n\n        self._check_bullet_alien_collisions()\n        \n\n    def _check_bullet_alien_collisions(self):\n        \"\"\"Respond to bullet-alien collisions.\"\"\"\n        # Remove any bullets and aliens that have collided.\n        collisions = pygame.sprite.groupcollide(\n                self.bullets, self.aliens, True, True)\n\n        if not self.aliens:\n            # Destroy existing bullets and create new fleet.\n            self.bullets.empty()\n            self._create_fleet()\n\n    def _ship_hit(self):\n        \"\"\"Respond to the ship being hit by an alien.\"\"\"\n        if self.stats.ships_left > 0:\n            # Decrement ships_left.\n            self.stats.ships_left -= 1\n\n            # Get rid of any remaining bullets and aliens.\n            self.bullets.empty()\n            self.aliens.empty()\n\n            # Create a new fleet and center the ship.\n            self._create_fleet()\n            self.ship.center_ship()\n\n            # Pause.\n            sleep(0.5)\n        else:\n            self.game_active = False\n            pygame.mouse.set_visible(True)\n\n    def _update_aliens(self):\n        \"\"\"Update the positions of all aliens in the fleet.\"\"\"\n        \"\"\"Check if the fleet is at an edge, then update positions.\"\"\"\n        self._check_fleet_edges()\n        self.aliens.update()\n\n        # Look for alien-ship collisions.\n        if pygame.sprite.spritecollideany(self.ship, self.aliens):\n            self._ship_hit()\n\n        # Look for aliens hitting the bottom of the screen.\n        self._check_aliens_bottom()\n\n    def _check_aliens_bottom(self):\n        \"\"\"Check if any aliens have reached the bottom of the screen.\"\"\"\n        for alien in self.aliens.sprites():\n            if alien.rect.bottom >= self.settings.screen_height:\n                # Treat this the same as if the ship got hit.\n                self._ship_hit()\n                break\n\n    def _create_fleet(self):\n        \"\"\"Create the fleet of aliens.\"\"\"\n        # Create an alien and keep adding aliens until there's no room left.\n        # Spacing between aliens is one alien width and one alien height.\n        alien = Alien(self)\n        alien_width, alien_height = alien.rect.size\n\n        current_x, current_y = alien_width, alien_height\n        while current_y < (self.settings.screen_height - 3 * alien_height):\n            while current_x < (self.settings.screen_width - 2 * alien_width):\n                self._create_alien(current_x, current_y)\n                current_x += 2 * alien_width\n\n            # Finished a row; reset x value, and increment y value.\n            current_x = alien_width\n            current_y += 2 * alien_height\n\n    def _create_alien(self, x_position, y_position):\n        \"\"\"Create an alien and place it in the fleet.\"\"\"\n        new_alien = Alien(self)\n        new_alien.x = x_position\n        new_alien.rect.x = x_position\n        new_alien.rect.y = y_position\n        self.aliens.add(new_alien)\n\n    def _check_fleet_edges(self):\n        \"\"\"Respond appropriately if any aliens have reached an edge.\"\"\"\n        for alien in self.aliens.sprites():\n            if alien.check_edges():\n                self._change_fleet_direction()\n                break\n\n    def _change_fleet_direction(self):\n        \"\"\"Drop the entire fleet and change the fleet's direction.\"\"\"\n        for alien in self.aliens.sprites():\n            alien.rect.y += self.settings.fleet_drop_speed\n        self.settings.fleet_direction *= -1\n\n    def _update_screen(self):\n        \"\"\"Update images on the screen, and flip to the new screen.\"\"\"\n        self.screen.fill(self.settings.bg_color)\n        for bullet in self.bullets.sprites():\n            bullet.draw_bullet()\n        self.ship.blitme()\n        self.aliens.draw(self.screen)\n\n        # Draw the play button if the game is inactive.\n        if not self.game_active:\n            self.play_button.draw_button()\n\n        pygame.display.flip()\n\n\nif __name__ == '__main__':\n    # Make a game instance, and run the game.\n    ai = AlienInvasion()\n    ai.run_game()","bullet.py":"import pygame\nfrom pygame.sprite import Sprite\n\nclass Bullet(Sprite):\n    \"\"\"A class to manage bullets fired from the ship.\"\"\"\n\n    def __init__(self, ai_game):\n        \"\"\"Create a bullet object at the ship's current position.\"\"\"\n        super().__init__()\n        self.screen = ai_game.screen\n        self.settings = ai_game.settings\n        self.color = self.settings.bullet_color\n\n        # Create a bullet rect at (0, 0) and then set correct position.\n        self.rect = pygame.Rect(0, 0, self.settings.bullet_width,\n            self.settings.bullet_height)\n        self.rect.midtop = ai_game.ship.rect.midtop\n\n        # Store the bullet's position as a float.\n        self.y = float(self.rect.y)\n\n    def update(self):\n        \"\"\"Move the bullet up the screen.\"\"\"\n        # Update the exact position of the bullet.\n        self.y -= self.settings.bullet_speed\n        # Update the rect position.\n        self.rect.y = self.y\n\n    def draw_bullet(self):\n        \"\"\"Draw the bullet to the screen.\"\"\"\n        pygame.draw.rect(self.screen, self.color, self.rect)","button.py":"import pygame.font\n\n\nclass Button:\n    \"\"\"A class to build buttons for the game.\"\"\"\n\n    def __init__(self, ai_game, msg):\n        \"\"\"Initialize button attributes.\"\"\"\n        self.screen = ai_game.screen\n        self.screen_rect = self.screen.get_rect()\n\n        # Set the dimensions and properties of the button.\n        self.width, self.height = 200, 50\n        self.button_color = (0, 135, 0)\n        self.text_color = (255, 255, 255)\n        self.font = pygame.font.SysFont(None, 48)\n\n        # Build the button's rect object and center it.\n        self.rect = pygame.Rect(0, 0, self.width, self.height)\n        self.rect.center = self.screen_rect.center\n\n        # The button message needs to be prepped only once.\n        self._prep_msg(msg)\n\n    def _prep_msg(self, msg):\n        \"\"\"Turn msg into a rendered image and center text on the button.\"\"\"\n        self.msg_image = self.font.render(msg, True, self.text_color,\n                self.button_color)\n        self.msg_image_rect = self.msg_image.get_rect()\n        self.msg_image_rect.center = self.rect.center\n\n    def draw_button(self):\n        \"\"\"Draw blank button and then draw message.\"\"\"\n        self.screen.fill(self.button_color, self.rect)\n        self.screen.blit(self.msg_image, self.msg_image_rect)","game_stats.py":"class GameStats:\n    \"\"\"Track statistics for Alien Invasion.\"\"\"\n\n    def __init__(self, ai_game):\n        \"\"\"Initialize statistics.\"\"\"\n        self.settings = ai_game.settings\n        self.reset_stats()\n\n    def reset_stats(self):\n        \"\"\"Initialize statistics that can change during the game.\"\"\"\n        self.ships_left = self.settings.ship_limit","images/alien.bmp":{"b64":""},"images/ship.bmp":{"b64":""},"settings.py":"class Settings:\n    \"\"\"A class to store all settings for Alien Invasion.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game's settings.\"\"\"\n        # Screen settings\n        self.screen_width = 1200\n        self.screen_height = 800\n        self.bg_color = (230, 230, 230)\n\n        # Ship settings.\n        self.ship_speed = 1.5\n        self.ship_limit = 3\n\n        # Bullet settings\n        self.bullet_speed = 2.5\n        self.bullet_width = 3\n        self.bullet_height = 15\n        self.bullet_color = (60, 60, 60)\n        self.bullets_allowed = 3\n\n        # Alien settings.\n        self.alien_speed = 1.0\n        self.fleet_drop_speed = 10\n        # fleet_direction of 1 represents right; -1 represents left.\n        self.fleet_direction = 1","ship.py":"import pygame\n\n\nclass Ship:\n    \"\"\"A class to manage the ship.\"\"\"\n\n    def __init__(self, ai_game):\n        \"\"\"Initialize the ship and set its starting position.\"\"\"\n        self.screen = ai_game.screen\n        self.settings = ai_game.settings\n        self.screen_rect = ai_game.screen.get_rect()\n\n        # Load the ship image and get its rect.\n        self.image = pygame.image.load('images/ship.bmp')\n        self.rect = self.image.get_rect()\n\n        # Start each new ship at the bottom center of the screen.\n        self.rect.midbottom = self.screen_rect.midbottom\n\n        # Store a float for the ship's exact horizontal position.\n        self.x = float(self.rect.x)\n\n        # Movement flags; start with a ship that's not moving.\n        self.moving_right = False\n        self.moving_left = False\n\n    def center_ship(self):\n        \"\"\"Center the ship on the screen.\"\"\"\n        self.rect.midbottom = self.screen_rect.midbottom\n        self.x = float(self.rect.x)\n\n    def update(self):\n        \"\"\"Update the ship's position based on movement flags.\"\"\"\n        # Update the ship's x value, not the rect.\n        if self.moving_right and self.rect.right < self.screen_rect.right:\n            self.x += self.settings.ship_speed\n        if self.moving_left and self.rect.left > 0:\n            self.x -= self.settings.ship_speed\n            \n        # Update rect object from self.x.\n        self.rect.x = self.x\n\n    def blitme(self):\n        \"\"\"Draw the ship at its current location.\"\"\"\n        self.screen.blit(self.image, self.rect)"}},"14-2":{"ch":14,"entry":"target_practice.py","mode":"run","reason":null,"files":{"bullet.py":"import pygame\nfrom pygame.sprite import Sprite\n \nclass Bullet(Sprite):\n    \"\"\"A class to manage bullets fired from the ship.\"\"\"\n\n    def __init__(self, ss_game):\n        \"\"\"Create a bullet object at the ship's current position.\"\"\"\n        super().__init__()\n        self.screen = ss_game.screen\n        self.settings = ss_game.settings\n        self.color = self.settings.bullet_color\n\n        # Create a bullet rect at (0, 0) and then set correct position.\n        self.rect = pygame.Rect(0, 0, self.settings.bullet_width,\n            self.settings.bullet_height)\n        self.rect.midright = ss_game.ship.rect.midright\n        \n        # Store the bullet's position as a decimal value.\n        self.x = float(self.rect.x)\n\n    def update(self):\n        \"\"\"Move the bullet across the screen.\"\"\"\n        # Update the decimal position of the bullet.\n        self.x += self.settings.bullet_speed\n        # Update the rect position.\n        self.rect.x = self.x\n\n    def draw_bullet(self):\n        \"\"\"Draw the bullet to the screen.\"\"\"\n        pygame.draw.rect(self.screen, self.color, self.rect)\n","button.py":"import pygame.font\n \nclass Button:\n \n    def __init__(self, ai_game, msg):\n        \"\"\"Initialize button attributes.\"\"\"\n        self.screen = ai_game.screen\n        self.screen_rect = self.screen.get_rect()\n        \n        # Set the dimensions and properties of the button.\n        self.width, self.height = 200, 50\n        self.button_color = (100, 5, 5)\n        self.text_color = (255, 255, 255)\n        self.font = pygame.font.SysFont(None, 48)\n        \n        # Build the button's rect object and center it.\n        self.rect = pygame.Rect(0, 0, self.width, self.height)\n        self.rect.center = self.screen_rect.center\n        \n        # The button message needs to be prepped only once.\n        self._prep_msg(msg)\n\n    def _prep_msg(self, msg):\n        \"\"\"Turn msg into a rendered image and center text on the button.\"\"\"\n        self.msg_image = self.font.render(msg, True, self.text_color,\n                self.button_color)\n        self.msg_image_rect = self.msg_image.get_rect()\n        self.msg_image_rect.center = self.rect.center\n\n    def draw_button(self):\n        # Draw blank button and then draw message.\n        self.screen.fill(self.button_color, self.rect)\n        self.screen.blit(self.msg_image, self.msg_image_rect)","game_stats.py":"class GameStats:\n    \"\"\"Track statistics for the game.\"\"\"\n\n    def __init__(self, ss_game):\n        \"\"\"Initialize statistics.\"\"\"\n        self.settings = ss_game.settings\n        self.reset_stats()\n\n    def reset_stats(self):\n        \"\"\"Initialize statistics that can change during the game.\"\"\"\n        self.ships_left = self.settings.ship_limit\n\n        self.num_misses = 0\n","images/GreenUFO_NoDmg.png":{"b64":""},"images/alien_ship.png":{"b64":""},"images/rocket_small.png":{"b64":""},"settings.py":"class Settings:\n    \"\"\"A class to store all settings for Sideways Shooter.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game's settings.\"\"\"\n        # Screen settings\n        self.screen_width = 1200\n        self.screen_height = 800\n        self.bg_color = (230, 230, 230)\n\n        # Ship settings\n        self.ship_speed = 3.0\n        self.ship_limit = 3\n\n        # Bullet settings\n        self.bullet_speed = 12.0\n        self.bullet_width = 15\n        self.bullet_height = 3\n        self.bullet_color = (60, 60, 60)\n        self.bullets_allowed = 3\n\n        # Target settings\n        self.target_height = 120\n        self.target_width = 15\n        self.target_color = (180, 60,10)\n\n        self.target_speed = 1.5\n\n        # Overall game dynamics.\n        self.miss_limit = 3","ship.py":"import pygame\n \nclass Ship:\n    \"\"\"A class to manage the ship.\"\"\"\n \n    def __init__(self, ss_game):\n        \"\"\"Initialize the ship and set its starting position.\"\"\"\n        self.screen = ss_game.screen\n        self.settings = ss_game.settings\n        self.screen_rect = ss_game.screen.get_rect()\n\n        # Load the ship image and get its rect.\n        self.image = pygame.image.load('images/rocket_small.png')\n        self.rect = self.image.get_rect()\n\n        # Start each new ship at the center of the left side of the screen.\n        self.center_ship()\n\n        # Movement flags\n        self.moving_up = False\n        self.moving_down = False\n\n    def update(self):\n        \"\"\"Update the ship's position based on movement flags.\"\"\"\n        # Update the ship's y value, not the rect.\n        if self.moving_up and self.rect.top > 0:\n            self.y -= self.settings.ship_speed\n        if self.moving_down and self.rect.bottom < self.screen_rect.bottom:\n            self.y += self.settings.ship_speed\n\n        # Update rect object from self.y.\n        self.rect.y = self.y\n\n    def center_ship(self):\n        \"\"\"Center the ship on the left side of the screen.\"\"\"\n        self.rect.midleft = self.screen_rect.midleft\n\n        # Store a decimal value for the ship's vertical position.\n        self.y = float(self.rect.y)\n\n    def blitme(self):\n        \"\"\"Draw the ship at its current location.\"\"\"\n        self.screen.blit(self.image, self.rect)\n","target.py":"import pygame\n \nclass Target:\n    \"\"\"A class to manage the target.\"\"\"\n\n    def __init__(self, ss_game):\n        \"\"\"Create a target object.\"\"\"\n        super().__init__()\n        self.screen = ss_game.screen\n        self.screen_rect = self.screen.get_rect()\n\n        self.settings = ss_game.settings\n        self.color = self.settings.target_color\n\n        # Create a target rect at (0, 0) and then set correct position.\n        self.rect = pygame.Rect(0, 0, self.settings.target_width,\n            self.settings.target_height)\n        self.center_target()\n\n        # Positive direction is moving down, negative is moving up.\n        self.direction = 1\n\n    def update(self):\n        \"\"\"Move the target steadily up and down.\"\"\"\n        # Update the decimal position of the target.\n        self.y += self.direction * self.settings.target_speed\n\n        if self.rect.top < 0:\n            # It's moved past the top of the screen. Place at top of screen,\n            #   and change direction.\n            self.rect.top = 0\n            self.direction = 1\n        elif self.rect.bottom > self.screen_rect.bottom:\n            # Place at bottom, and change direction.\n            self.rect.bottom = self.screen_rect.bottom\n            self.direction = -1\n\n        # Update the rect position.\n        self.rect.y = self.y\n\n    def center_target(self):\n        \"\"\"Center the target on the right side of the screen.\"\"\"\n        self.rect.midright = self.screen_rect.midright\n        \n        # Store the target's position as a decimal value.\n        self.y = float(self.rect.y)\n\n    def draw_target(self):\n        \"\"\"Draw the target to the screen.\"\"\"\n        pygame.draw.rect(self.screen, self.color, self.rect)\n","target_practice.py":"import sys\nfrom random import random\n\nimport pygame\n\nfrom settings import Settings\nfrom game_stats import GameStats\nfrom button import Button\nfrom ship import Ship\nfrom bullet import Bullet\nfrom target import Target\n\nclass TargetPractice:\n    \"\"\"Overall class to manage game assets and behavior.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game, and create game resources.\"\"\"\n        pygame.init()\n        self.clock = pygame.time.Clock()\n        self.settings = Settings()\n\n        self.screen = pygame.display.set_mode(\n                (self.settings.screen_width, self.settings.screen_height))\n        pygame.display.set_caption(\"Target Practice\")\n\n        # Create an instance to store game statistics.\n        self.stats = GameStats(self)\n\n        self.ship = Ship(self)\n        self.bullets = pygame.sprite.Group()\n        self.target = Target(self)\n\n        # Make the Play button.\n        self.play_button = Button(self, \"Play\")\n\n        # Start game in an inactive state.\n        self.game_active = False\n\n    def run_game(self):\n        \"\"\"Start the main loop for the game.\"\"\"\n        while True:\n            self._check_events()\n\n            if self.game_active:\n                self.ship.update()\n                self._update_bullets()\n                self.target.update()\n            \n            self._update_screen()\n            self.clock.tick(60)\n\n    def _check_events(self):\n        \"\"\"Respond to keypresses and mouse events.\"\"\"\n        for event in pygame.event.get():\n            if event.type == pygame.QUIT:\n                sys.exit()\n            elif event.type == pygame.KEYDOWN:\n                self._check_keydown_events(event)\n            elif event.type == pygame.KEYUP:\n                self._check_keyup_events(event)\n            elif event.type == pygame.MOUSEBUTTONDOWN:\n                mouse_pos = pygame.mouse.get_pos()\n                self._check_play_button(mouse_pos)\n\n    def _check_play_button(self, mouse_pos):\n        \"\"\"Start a new game when the player clicks Play.\"\"\"\n        button_clicked = self.play_button.rect.collidepoint(mouse_pos)\n        if button_clicked and not self.game_active:\n            self._start_game()\n\n    def _start_game(self):\n        \"\"\"Start a new game.\"\"\"\n        # Reset the game statistics.\n        self.stats.reset_stats()\n        self.game_active = True\n\n        # Get rid of any remaining bullets.\n        self.bullets.empty()\n\n        # Center the ship and target.\n        self.ship.center_ship()\n        self.target.center_target()\n\n        # Hide the mouse cursor.\n        pygame.mouse.set_visible(False)\n\n    def _check_keydown_events(self, event):\n        \"\"\"Respond to keypresses.\"\"\"\n        if event.key == pygame.K_UP:\n            self.ship.moving_up = True\n        elif event.key == pygame.K_DOWN:\n            self.ship.moving_down = True\n        elif event.key == pygame.K_SPACE:\n            self._fire_bullet()\n        elif event.key == pygame.K_q:\n            sys.exit()\n\n    def _check_keyup_events(self, event):\n        \"\"\"Respond to key releases.\"\"\"\n        if event.key == pygame.K_UP:\n            self.ship.moving_up = False\n        elif event.key == pygame.K_DOWN:\n            self.ship.moving_down = False\n\n    def _fire_bullet(self):\n        \"\"\"Create a new bullet and add it to the bullets group.\"\"\"\n        if len(self.bullets) < self.settings.bullets_allowed:\n            new_bullet = Bullet(self)\n            self.bullets.add(new_bullet)\n\n    def _update_bullets(self):\n        \"\"\"Update position of bullets and get rid of old bullets.\n        Also, update stats for number of misses.\n        \"\"\"\n        # Update bullet positions.\n        self.bullets.update()\n\n        # Get rid of bullets that have disappeared.\n        for bullet in self.bullets.copy():\n            if bullet.rect.left >= self.screen.get_rect().right:\n                self.bullets.remove(bullet)\n                self._increment_misses()\n\n        self._check_bullet_target_collisions()\n\n    def _increment_misses(self):\n        \"\"\"Increment the number of misses, and check if the game shold end.\"\"\"\n        self.stats.num_misses += 1\n        if self.stats.num_misses >= self.settings.miss_limit:\n            self.game_active = False\n            pygame.mouse.set_visible(True)\n\n    def _check_bullet_target_collisions(self):\n        \"\"\"Check whether any bullets have hit the target.\"\"\"\n        collisions = pygame.sprite.spritecollide(\n                self.target, self.bullets, True)\n\n    def _update_screen(self):\n        \"\"\"Update images on the screen, and flip to the new screen.\"\"\"\n        self.screen.fill(self.settings.bg_color)\n        self.ship.blitme()\n        for bullet in self.bullets.sprites():\n            bullet.draw_bullet()\n\n        self.target.draw_target()\n\n        # Draw the play button if the game is inactive.\n        if not self.game_active:\n            self.play_button.draw_button()\n\n        pygame.display.flip()\n\n\nif __name__ == '__main__':\n    # Make a game instance, and run the game.\n    tp_game = TargetPractice()\n    tp_game.run_game()"}},"14-3":{"ch":14,"entry":"target_practice.py","mode":"run","reason":null,"files":{"bullet.py":"import pygame\nfrom pygame.sprite import Sprite\n \nclass Bullet(Sprite):\n    \"\"\"A class to manage bullets fired from the ship.\"\"\"\n\n    def __init__(self, ss_game):\n        \"\"\"Create a bullet object at the ship's current position.\"\"\"\n        super().__init__()\n        self.screen = ss_game.screen\n        self.settings = ss_game.settings\n        self.color = self.settings.bullet_color\n\n        # Create a bullet rect at (0, 0) and then set correct position.\n        self.rect = pygame.Rect(0, 0, self.settings.bullet_width,\n            self.settings.bullet_height)\n        self.rect.midright = ss_game.ship.rect.midright\n        \n        # Store the bullet's position as a decimal value.\n        self.x = float(self.rect.x)\n\n    def update(self):\n        \"\"\"Move the bullet across the screen.\"\"\"\n        # Update the decimal position of the bullet.\n        self.x += self.settings.bullet_speed\n        # Update the rect position.\n        self.rect.x = self.x\n\n    def draw_bullet(self):\n        \"\"\"Draw the bullet to the screen.\"\"\"\n        pygame.draw.rect(self.screen, self.color, self.rect)\n","button.py":"import pygame.font\n \nclass Button:\n \n    def __init__(self, ai_game, msg):\n        \"\"\"Initialize button attributes.\"\"\"\n        self.screen = ai_game.screen\n        self.screen_rect = self.screen.get_rect()\n        \n        # Set the dimensions and properties of the button.\n        self.width, self.height = 200, 50\n        self.button_color = (100, 5, 5)\n        self.text_color = (255, 255, 255)\n        self.font = pygame.font.SysFont(None, 48)\n        \n        # Build the button's rect object and center it.\n        self.rect = pygame.Rect(0, 0, self.width, self.height)\n        self.rect.center = self.screen_rect.center\n        \n        # The button message needs to be prepped only once.\n        self._prep_msg(msg)\n\n    def _prep_msg(self, msg):\n        \"\"\"Turn msg into a rendered image and center text on the button.\"\"\"\n        self.msg_image = self.font.render(msg, True, self.text_color,\n                self.button_color)\n        self.msg_image_rect = self.msg_image.get_rect()\n        self.msg_image_rect.center = self.rect.center\n\n    def draw_button(self):\n        # Draw blank button and then draw message.\n        self.screen.fill(self.button_color, self.rect)\n        self.screen.blit(self.msg_image, self.msg_image_rect)","game_stats.py":"class GameStats:\n    \"\"\"Track statistics for the game.\"\"\"\n\n    def __init__(self, ss_game):\n        \"\"\"Initialize statistics.\"\"\"\n        self.settings = ss_game.settings\n        self.reset_stats()\n\n    def reset_stats(self):\n        \"\"\"Initialize statistics that can change during the game.\"\"\"\n        self.ships_left = self.settings.ship_limit\n        self.num_misses = 0\n        self.num_hits = 0\n","images/GreenUFO_NoDmg.png":{"b64":""},"images/alien_ship.png":{"b64":""},"images/rocket_small.png":{"b64":""},"settings.py":"class Settings:\n    \"\"\"A class to store all settings for Sideways Shooter.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game's settings.\"\"\"\n        # Screen settings\n        self.screen_width = 1200\n        self.screen_height = 800\n        self.bg_color = (230, 230, 230)\n\n        # Ship settings\n        self.ship_limit = 3\n\n        # Bullet settings\n        self.bullet_width = 15\n        self.bullet_height = 3\n        self.bullet_color = (60, 60, 60)\n        self.bullets_allowed = 3\n\n        # Target settings\n        self.target_height = 120\n        self.target_width = 15\n        self.target_color = (180, 60,10)\n\n        # Overall game dynamics.\n        self.miss_limit = 3\n        self.speedup_scale = 2.1\n        # After every levelup_hits, level up the difficulty.\n        self.levelup_hits = 10\n\n        self.initialize_dynamic_settings()\n\n    def initialize_dynamic_settings(self):\n        \"\"\"Initialize settings that change throughout the game.\"\"\"\n        self.ship_speed = 3.0\n        self.bullet_speed = 12.0\n        self.target_speed = 1.5\n\n    def increase_speed(self):\n        \"\"\"Increase speed settings.\"\"\"\n        self.ship_speed *= self.speedup_scale\n        self.bullet_speed *= self.speedup_scale\n        self.target_speed *= self.speedup_scale","ship.py":"import pygame\n \nclass Ship:\n    \"\"\"A class to manage the ship.\"\"\"\n \n    def __init__(self, ss_game):\n        \"\"\"Initialize the ship and set its starting position.\"\"\"\n        self.screen = ss_game.screen\n        self.settings = ss_game.settings\n        self.screen_rect = ss_game.screen.get_rect()\n\n        # Load the ship image and get its rect.\n        self.image = pygame.image.load('images/rocket_small.png')\n        self.rect = self.image.get_rect()\n\n        # Start each new ship at the center of the left side of the screen.\n        self.center_ship()\n\n        # Movement flags\n        self.moving_up = False\n        self.moving_down = False\n\n    def update(self):\n        \"\"\"Update the ship's position based on movement flags.\"\"\"\n        # Update the ship's y value, not the rect.\n        if self.moving_up and self.rect.top > 0:\n            self.y -= self.settings.ship_speed\n        if self.moving_down and self.rect.bottom < self.screen_rect.bottom:\n            self.y += self.settings.ship_speed\n\n        # Update rect object from self.y.\n        self.rect.y = self.y\n\n    def center_ship(self):\n        \"\"\"Center the ship on the left side of the screen.\"\"\"\n        self.rect.midleft = self.screen_rect.midleft\n\n        # Store a decimal value for the ship's vertical position.\n        self.y = float(self.rect.y)\n\n    def blitme(self):\n        \"\"\"Draw the ship at its current location.\"\"\"\n        self.screen.blit(self.image, self.rect)\n","target.py":"import pygame\n \nclass Target:\n    \"\"\"A class to manage the target.\"\"\"\n\n    def __init__(self, ss_game):\n        \"\"\"Create a target object.\"\"\"\n        super().__init__()\n        self.screen = ss_game.screen\n        self.screen_rect = self.screen.get_rect()\n\n        self.settings = ss_game.settings\n        self.color = self.settings.target_color\n\n        # Create a target rect at (0, 0) and then set correct position.\n        self.rect = pygame.Rect(0, 0, self.settings.target_width,\n            self.settings.target_height)\n        self.center_target()\n\n        # Positive direction is moving down, negative is moving up.\n        self.direction = 1\n\n    def update(self):\n        \"\"\"Move the target steadily up and down.\"\"\"\n        # Update the decimal position of the target.\n        self.y += self.direction * self.settings.target_speed\n\n        if self.rect.top < 0:\n            # It's moved past the top of the screen. Place at top of screen,\n            #   and change direction.\n            self.rect.top = 0\n            self.direction = 1\n        elif self.rect.bottom > self.screen_rect.bottom:\n            # Place at bottom, and change direction.\n            self.rect.bottom = self.screen_rect.bottom\n            self.direction = -1\n\n        # Update the rect position.\n        self.rect.y = self.y\n\n    def center_target(self):\n        \"\"\"Center the target on the right side of the screen.\"\"\"\n        self.rect.midright = self.screen_rect.midright\n        \n        # Store the target's position as a decimal value.\n        self.y = float(self.rect.y)\n\n    def draw_target(self):\n        \"\"\"Draw the target to the screen.\"\"\"\n        pygame.draw.rect(self.screen, self.color, self.rect)\n","target_practice.py":"import sys\nfrom random import random\n\nimport pygame\n\nfrom settings import Settings\nfrom game_stats import GameStats\nfrom button import Button\nfrom ship import Ship\nfrom bullet import Bullet\nfrom target import Target\n\nclass TargetPractice:\n    \"\"\"Overall class to manage game assets and behavior.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game, and create game resources.\"\"\"\n        pygame.init()\n        self.clock = pygame.time.Clock()\n        self.settings = Settings()\n\n        self.screen = pygame.display.set_mode(\n                (self.settings.screen_width, self.settings.screen_height))\n        pygame.display.set_caption(\"Target Practice\")\n\n        # Create an instance to store game statistics.\n        self.stats = GameStats(self)\n\n        self.ship = Ship(self)\n        self.bullets = pygame.sprite.Group()\n        self.target = Target(self)\n\n        # Make the Play button.\n        self.play_button = Button(self, \"Play\")\n\n        # Start game in an inactive state.\n        self.game_active = False\n\n    def run_game(self):\n        \"\"\"Start the main loop for the game.\"\"\"\n        while True:\n            self._check_events()\n\n            if self.game_active:\n                self.ship.update()\n                self._update_bullets()\n                self.target.update()\n            \n            self._update_screen()\n            self.clock.tick(60)\n\n    def _check_events(self):\n        \"\"\"Respond to keypresses and mouse events.\"\"\"\n        for event in pygame.event.get():\n            if event.type == pygame.QUIT:\n                sys.exit()\n            elif event.type == pygame.KEYDOWN:\n                self._check_keydown_events(event)\n            elif event.type == pygame.KEYUP:\n                self._check_keyup_events(event)\n            elif event.type == pygame.MOUSEBUTTONDOWN:\n                mouse_pos = pygame.mouse.get_pos()\n                self._check_play_button(mouse_pos)\n\n    def _check_play_button(self, mouse_pos):\n        \"\"\"Start a new game when the player clicks Play.\"\"\"\n        button_clicked = self.play_button.rect.collidepoint(mouse_pos)\n        if button_clicked and not self.game_active:\n            self._start_game()\n\n    def _start_game(self):\n        \"\"\"Start a new game.\"\"\"\n        # Reset dynamic settings and game statistics.\n        self.settings.initialize_dynamic_settings()\n        self.stats.reset_stats()\n        self.game_active = True\n\n        # Get rid of any remaining bullets.\n        self.bullets.empty()\n\n        # Center the ship and target.\n        self.ship.center_ship()\n        self.target.center_target()\n\n        # Hide the mouse cursor.\n        pygame.mouse.set_visible(False)\n\n    def _check_keydown_events(self, event):\n        \"\"\"Respond to keypresses.\"\"\"\n        if event.key == pygame.K_UP:\n            self.ship.moving_up = True\n        elif event.key == pygame.K_DOWN:\n            self.ship.moving_down = True\n        elif event.key == pygame.K_SPACE:\n            self._fire_bullet()\n        elif event.key == pygame.K_q:\n            sys.exit()\n\n    def _check_keyup_events(self, event):\n        \"\"\"Respond to key releases.\"\"\"\n        if event.key == pygame.K_UP:\n            self.ship.moving_up = False\n        elif event.key == pygame.K_DOWN:\n            self.ship.moving_down = False\n\n    def _fire_bullet(self):\n        \"\"\"Create a new bullet and add it to the bullets group.\"\"\"\n        if len(self.bullets) < self.settings.bullets_allowed:\n            new_bullet = Bullet(self)\n            self.bullets.add(new_bullet)\n\n    def _update_bullets(self):\n        \"\"\"Update position of bullets and get rid of old bullets.\n        Also, update stats for number of misses.\n        \"\"\"\n        # Update bullet positions.\n        self.bullets.update()\n\n        # Get rid of bullets that have disappeared.\n        for bullet in self.bullets.copy():\n            if bullet.rect.left >= self.screen.get_rect().right:\n                self.bullets.remove(bullet)\n                self._increment_misses()\n\n        self._check_bullet_target_collisions()\n\n    def _increment_misses(self):\n        \"\"\"Increment the number of misses, and check if the game shold end.\"\"\"\n        self.stats.num_misses += 1\n        if self.stats.num_misses >= self.settings.miss_limit:\n            self.game_active = False\n            pygame.mouse.set_visible(True)\n\n    def _check_bullet_target_collisions(self):\n        \"\"\"Check whether any bullets have hit the target.\"\"\"\n        collisions = pygame.sprite.spritecollide(\n                self.target, self.bullets, True)\n\n        if collisions:\n            # Update stats, and see if game should speed up.\n            self.stats.num_hits += 1\n            if self.stats.num_hits % self.settings.levelup_hits == 0:\n                self.settings.increase_speed()\n\n    def _update_screen(self):\n        \"\"\"Update images on the screen, and flip to the new screen.\"\"\"\n        self.screen.fill(self.settings.bg_color)\n        self.ship.blitme()\n        for bullet in self.bullets.sprites():\n            bullet.draw_bullet()\n\n        self.target.draw_target()\n\n        # Draw the play button if the game is inactive.\n        if not self.game_active:\n            self.play_button.draw_button()\n\n        pygame.display.flip()\n\n\nif __name__ == '__main__':\n    # Make a game instance, and run the game.\n    tp_game = TargetPractice()\n    tp_game.run_game()"}},"14-4":{"ch":14,"entry":"alien_invasion.py","mode":"run","reason":null,"files":{"alien.py":"import pygame\nfrom pygame.sprite import Sprite\n \nclass Alien(Sprite):\n    \"\"\"A class to represent a single alien in the fleet.\"\"\"\n\n    def __init__(self, ai_game):\n        \"\"\"Initialize the alien and set its starting position.\"\"\"\n        super().__init__()\n        self.screen = ai_game.screen\n        self.settings = ai_game.settings\n\n        # Load the alien image and set its rect attribute.\n        self.image = pygame.image.load('images/alien.bmp')\n        self.rect = self.image.get_rect()\n\n        # Start each new alien near the top left of the screen.\n        self.rect.x = self.rect.width\n        self.rect.y = self.rect.height\n\n        # Store the alien's exact horizontal position.\n        self.x = float(self.rect.x)\n\n    def check_edges(self):\n        \"\"\"Return True if alien is at edge of screen.\"\"\"\n        screen_rect = self.screen.get_rect()\n        if self.rect.right >= screen_rect.right or self.rect.left <= 0:\n            return True\n\n    def update(self):\n        \"\"\"Move the alien right or left.\"\"\"\n        self.x += (self.settings.alien_speed *\n                        self.settings.fleet_direction)\n        self.rect.x = self.x\n","alien_invasion.py":"import sys\nfrom time import sleep\n\nimport pygame\n\nfrom settings import Settings\nfrom game_stats import GameStats\nfrom button import Button\nfrom ship import Ship\nfrom bullet import Bullet\nfrom alien import Alien\n\n\nclass AlienInvasion:\n    \"\"\"Overall class to manage game assets and behavior.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game, and create game resources.\"\"\"\n        pygame.init()\n        self.clock = pygame.time.Clock()\n        self.settings = Settings()\n\n        self.screen = pygame.display.set_mode(\n                (self.settings.screen_width, self.settings.screen_height))\n        pygame.display.set_caption(\"Alien Invasion\")\n\n        # Create an instance to store game statistics.\n        self.stats = GameStats(self)\n\n        self.ship = Ship(self)\n        self.bullets = pygame.sprite.Group()\n        self.aliens = pygame.sprite.Group()\n\n        self._create_fleet()\n\n        # Make the Play button.\n        self.play_button = Button(self, \"Play\")\n\n        # Make difficulty level buttons.\n        self._make_difficulty_buttons()\n\n        # Start game in an inactive state.\n        self.game_active = False\n\n    def _make_difficulty_buttons(self):\n        \"\"\"Make buttons that allow player to select difficulty level.\"\"\"\n        self.easy_button = Button(self, \"Easy\")\n        self.medium_button = Button(self, \"Medium\")\n        self.difficult_button = Button(self, \"Difficult\")\n\n        # Position buttons so they don't all overlap.\n        self.easy_button.rect.top = (\n            self.play_button.rect.top + 1.5*self.play_button.rect.height)\n        self.easy_button._update_msg_position()\n\n        self.medium_button.rect.top = (\n            self.easy_button.rect.top + 1.5*self.easy_button.rect.height)\n        self.medium_button._update_msg_position()\n\n        self.difficult_button.rect.top = (\n            self.medium_button.rect.top + 1.5*self.medium_button.rect.height)\n        self.difficult_button._update_msg_position()\n\n    def run_game(self):\n        \"\"\"Start the main loop for the game.\"\"\"\n        while True:\n            self._check_events()\n\n            if self.game_active:\n                self.ship.update()\n                self._update_bullets()\n                self._update_aliens()\n\n            self._update_screen()\n            self.clock.tick(60)\n\n    def _check_events(self):\n        \"\"\"Respond to keypresses and mouse events.\"\"\"\n        for event in pygame.event.get():\n            if event.type == pygame.QUIT:\n                sys.exit()\n            elif event.type == pygame.KEYDOWN:\n                self._check_keydown_events(event)\n            elif event.type == pygame.KEYUP:\n                self._check_keyup_events(event)\n            elif event.type == pygame.MOUSEBUTTONDOWN:\n                mouse_pos = pygame.mouse.get_pos()\n                self._check_play_button(mouse_pos)\n                self._check_difficulty_buttons(mouse_pos)\n\n    def _check_play_button(self, mouse_pos):\n        \"\"\"Start a new game when the player clicks Play.\"\"\"\n        button_clicked = self.play_button.rect.collidepoint(mouse_pos)\n        if button_clicked and not self.game_active:\n            self._start_game()\n\n    def _check_difficulty_buttons(self, mouse_pos):\n        \"\"\"Set the appropriate difficulty level.\"\"\"\n        easy_button_clicked = self.easy_button.rect.collidepoint(mouse_pos)\n        medium_button_clicked = self.medium_button.rect.collidepoint(\n                mouse_pos)\n        diff_button_clicked = self.difficult_button.rect.collidepoint(\n                mouse_pos)\n        if easy_button_clicked:\n            self.settings.difficulty_level = 'easy'\n        elif medium_button_clicked:\n            self.settings.difficulty_level = 'medium'\n        elif diff_button_clicked:\n            self.settings.difficulty_level = 'difficult'\n\n    def _start_game(self):\n        \"\"\"Start a new game.\"\"\"\n        # Reset the game settings.\n        self.settings.initialize_dynamic_settings()\n\n        # Reset the game statistics.\n        self.stats.reset_stats()\n        self.game_active = True\n\n        # Get rid of any remaining aliens and bullets.\n        self.aliens.empty()\n        self.bullets.empty()\n        \n        # Create a new fleet and center the ship.\n        self._create_fleet()\n        self.ship.center_ship()\n\n        # Hide the mouse cursor.\n        pygame.mouse.set_visible(False)\n\n    def _check_keydown_events(self, event):\n        \"\"\"Respond to keypresses.\"\"\"\n        if event.key == pygame.K_RIGHT:\n            self.ship.moving_right = True\n        elif event.key == pygame.K_LEFT:\n            self.ship.moving_left = True\n        elif event.key == pygame.K_q:\n            sys.exit()\n        elif event.key == pygame.K_SPACE:\n            self._fire_bullet()\n        elif event.key == pygame.K_p and not self.game_active:\n            self._start_game()\n\n    def _check_keyup_events(self, event):\n        \"\"\"Respond to key releases.\"\"\"\n        if event.key == pygame.K_RIGHT:\n            self.ship.moving_right = False\n        elif event.key == pygame.K_LEFT:\n            self.ship.moving_left = False\n\n    def _fire_bullet(self):\n        \"\"\"Create a new bullet and add it to the bullets group.\"\"\"\n        if len(self.bullets) < self.settings.bullets_allowed:\n            new_bullet = Bullet(self)\n            self.bullets.add(new_bullet)\n\n    def _update_bullets(self):\n        \"\"\"Update position of bullets and get rid of old bullets.\"\"\"\n        # Update bullet positions.\n        self.bullets.update()\n\n        # Get rid of bullets that have disappeared.\n        for bullet in self.bullets.copy():\n            if bullet.rect.bottom <= 0:\n                 self.bullets.remove(bullet)\n\n        self._check_bullet_alien_collisions()\n\n    def _check_bullet_alien_collisions(self):\n        \"\"\"Respond to bullet-alien collisions.\"\"\"\n        # Remove any bullets and aliens that have collided.\n        collisions = pygame.sprite.groupcollide(\n                self.bullets, self.aliens, True, True)\n\n        if not self.aliens:\n            # Destroy existing bullets and create new fleet.\n            self.bullets.empty()\n            self._create_fleet()\n            self.settings.increase_speed()\n\n    def _update_aliens(self):\n        \"\"\"\n        Check if the fleet is at an edge,\n          then update the positions of all aliens in the fleet.\n        \"\"\"\n        self._check_fleet_edges()\n        self.aliens.update()\n\n        # Look for alien-ship collisions.\n        if pygame.sprite.spritecollideany(self.ship, self.aliens):\n            self._ship_hit()\n\n        # Look for aliens hitting the bottom of the screen.\n        self._check_aliens_bottom()\n\n    def _check_aliens_bottom(self):\n        \"\"\"Check if any aliens have reached the bottom of the screen.\"\"\"\n        screen_rect = self.screen.get_rect()\n        for alien in self.aliens.sprites():\n            if alien.rect.bottom >= screen_rect.bottom:\n                # Treat this the same as if the ship got hit.\n                self._ship_hit()\n                break\n\n    def _ship_hit(self):\n        \"\"\"Respond to the ship being hit by an alien.\"\"\"\n        if self.stats.ships_left > 0:\n            # Decrement ships_left.\n            self.stats.ships_left -= 1\n            \n            # Get rid of any remaining aliens and bullets.\n            self.aliens.empty()\n            self.bullets.empty()\n            \n            # Create a new fleet and center the ship.\n            self._create_fleet()\n            self.ship.center_ship()\n            \n            # Pause.\n            sleep(0.5)\n        else:\n            self.game_active = False\n            pygame.mouse.set_visible(True)\n\n    def _create_fleet(self):\n        \"\"\"Create the fleet of aliens.\"\"\"\n        # Create an alien and find the number of aliens in a row.\n        # Spacing between each alien is equal to one alien width.\n        alien = Alien(self)\n        alien_width, alien_height = alien.rect.size\n        available_space_x = self.settings.screen_width - (2 * alien_width)\n        number_aliens_x = available_space_x // (2 * alien_width)\n        \n        # Determine the number of rows of aliens that fit on the screen.\n        ship_height = self.ship.rect.height\n        available_space_y = (self.settings.screen_height -\n                                (3 * alien_height) - ship_height)\n        number_rows = available_space_y // (2 * alien_height)\n        \n        # Create the full fleet of aliens.\n        for row_number in range(number_rows):\n            for alien_number in range(number_aliens_x):\n                self._create_alien(alien_number, row_number)\n\n    def _create_alien(self, alien_number, row_number):\n        \"\"\"Create an alien and place it in the row.\"\"\"\n        alien = Alien(self)\n        alien_width, alien_height = alien.rect.size\n        alien.x = alien_width + 2 * alien_width * alien_number\n        alien.rect.x = alien.x\n        alien.rect.y = alien.rect.height + 2 * alien.rect.height * row_number\n        self.aliens.add(alien)\n\n    def _check_fleet_edges(self):\n        \"\"\"Respond appropriately if any aliens have reached an edge.\"\"\"\n        for alien in self.aliens.sprites():\n            if alien.check_edges():\n                self._change_fleet_direction()\n                break\n            \n    def _change_fleet_direction(self):\n        \"\"\"Drop the entire fleet and change the fleet's direction.\"\"\"\n        for alien in self.aliens.sprites():\n            alien.rect.y += self.settings.fleet_drop_speed\n        self.settings.fleet_direction *= -1\n\n    def _update_screen(self):\n        \"\"\"Update images on the screen, and flip to the new screen.\"\"\"\n        self.screen.fill(self.settings.bg_color)\n        self.ship.blitme()\n        for bullet in self.bullets.sprites():\n            bullet.draw_bullet()\n        self.aliens.draw(self.screen)\n\n        # Draw the play button if the game is inactive.\n        if not self.game_active:\n            self.play_button.draw_button()\n            self.easy_button.draw_button()\n            self.medium_button.draw_button()\n            self.difficult_button.draw_button()\n\n        pygame.display.flip()\n\n\nif __name__ == '__main__':\n    # Make a game instance, and run the game.\n    ai = AlienInvasion()\n    ai.run_game()\n","bullet.py":"import pygame\nfrom pygame.sprite import Sprite\n \nclass Bullet(Sprite):\n    \"\"\"A class to manage bullets fired from the ship\"\"\"\n\n    def __init__(self, ai_game):\n        \"\"\"Create a bullet object at the ship's current position.\"\"\"\n        super().__init__()\n        self.screen = ai_game.screen\n        self.settings = ai_game.settings\n        self.color = self.settings.bullet_color\n\n        # Create a bullet rect at (0, 0) and then set correct position.\n        self.rect = pygame.Rect(0, 0, self.settings.bullet_width,\n            self.settings.bullet_height)\n        self.rect.midtop = ai_game.ship.rect.midtop\n        \n        # Store the bullet's position as a decimal value.\n        self.y = float(self.rect.y)\n\n    def update(self):\n        \"\"\"Move the bullet up the screen.\"\"\"\n        # Update the decimal position of the bullet.\n        self.y -= self.settings.bullet_speed\n        # Update the rect position.\n        self.rect.y = self.y\n\n    def draw_bullet(self):\n        \"\"\"Draw the bullet to the screen.\"\"\"\n        pygame.draw.rect(self.screen, self.color, self.rect)\n","button.py":"import pygame.font\n \nclass Button:\n \n    def __init__(self, ai_game, msg):\n        \"\"\"Initialize button attributes.\"\"\"\n        self.screen = ai_game.screen\n        self.screen_rect = self.screen.get_rect()\n        \n        # Set the dimensions and properties of the button.\n        self.width, self.height = 200, 50\n        self.button_color = (0, 135, 0)\n        self.text_color = (255, 255, 255)\n        self.font = pygame.font.SysFont(None, 48)\n        \n        # Build the button's rect object and center it.\n        self.rect = pygame.Rect(0, 0, self.width, self.height)\n        self.rect.center = self.screen_rect.center\n        \n        # The button message needs to be prepped only once.\n        self._prep_msg(msg)\n\n    def _prep_msg(self, msg):\n        \"\"\"Turn msg into a rendered image and center text on the button.\"\"\"\n        self.msg_image = self.font.render(msg, True, self.text_color,\n                self.button_color)\n        self.msg_image_rect = self.msg_image.get_rect()\n        self.msg_image_rect.center = self.rect.center\n\n    def _update_msg_position(self):\n        \"\"\"If the button has been moved, the text needs to be moved as well.\"\"\"\n        self.msg_image_rect.center = self.rect.center\n\n    def draw_button(self):\n        # Draw blank button and then draw message.\n        self.screen.fill(self.button_color, self.rect)\n        self.screen.blit(self.msg_image, self.msg_image_rect)","game_stats.py":"class GameStats:\n    \"\"\"Track statistics for Alien Invasion.\"\"\"\n    \n    def __init__(self, ai_game):\n        \"\"\"Initialize statistics.\"\"\"\n        self.settings = ai_game.settings\n        self.reset_stats()\n        \n    def reset_stats(self):\n        \"\"\"Initialize statistics that can change during the game.\"\"\"\n        self.ships_left = self.settings.ship_limit","images/alien.bmp":{"b64":""},"images/ship.bmp":{"b64":""},"settings.py":"class Settings:\n    \"\"\"A class to store all settings for Alien Invasion.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game's static settings.\"\"\"\n        # Screen settings\n        self.screen_width = 1200\n        self.screen_height = 800\n        self.bg_color = (230, 230, 230)\n\n        # Ship settings\n        self.ship_limit = 3\n\n        # Bullet settings\n        self.bullet_width = 3\n        self.bullet_height = 15\n        self.bullet_color = (60, 60, 60)\n        self.bullets_allowed = 3\n\n        # Alien settings\n        self.fleet_drop_speed = 10\n\n        # How quickly the game speeds up\n        self.speedup_scale = 1.1\n\n        self.difficulty_level = 'medium'\n\n        self.initialize_dynamic_settings()\n\n    def initialize_dynamic_settings(self):\n        \"\"\"Initialize settings that change throughout the game.\"\"\"\n        if self.difficulty_level == 'easy':\n            self.ship_limit = 5\n            self.bullets_allowed = 10\n            self.ship_speed = 0.75\n            self.bullet_speed = 1.5\n            self.alien_speed = 0.5\n        elif self.difficulty_level == 'medium':\n            self.ship_limit = 3\n            self.bullets_allowed = 3\n            self.ship_speed = 1.5\n            self.bullet_speed = 3.0\n            self.alien_speed = 1.0\n        elif self.difficulty_level == 'difficult':\n            self.ship_limit = 2\n            self.bullets_allowed = 3\n            self.ship_speed = 3.0\n            self.bullet_speed = 6.0\n            self.alien_speed = 2.0\n\n        # fleet_direction of 1 represents right; -1 represents left.\n        self.fleet_direction = 1\n\n    def increase_speed(self):\n        \"\"\"Increase speed settings.\"\"\"\n        self.ship_speed *= self.speedup_scale\n        self.bullet_speed *= self.speedup_scale\n        self.alien_speed *= self.speedup_scale\n\n    def set_difficulty(self, diff_setting):\n        if diff_setting == 'easy':\n            print('easy')\n        elif diff_setting == 'medium':\n            pass\n        elif diff_setting == 'difficult':\n            pass\n","ship.py":"import pygame\n \nclass Ship:\n    \"\"\"A class to manage the ship.\"\"\"\n \n    def __init__(self, ai_game):\n        \"\"\"Initialize the ship and set its starting position.\"\"\"\n        self.screen = ai_game.screen\n        self.settings = ai_game.settings\n        self.screen_rect = ai_game.screen.get_rect()\n\n        # Load the ship image and get its rect.\n        self.image = pygame.image.load('images/ship.bmp')\n        self.rect = self.image.get_rect()\n\n        # Start each new ship at the bottom center of the screen.\n        self.rect.midbottom = self.screen_rect.midbottom\n\n        # Store a decimal value for the ship's horizontal position.\n        self.x = float(self.rect.x)\n\n        # Movement flags\n        self.moving_right = False\n        self.moving_left = False\n\n    def update(self):\n        \"\"\"Update the ship's position based on movement flags.\"\"\"\n        # Update the ship's x value, not the rect.\n        if self.moving_right and self.rect.right < self.screen_rect.right:\n            self.x += self.settings.ship_speed\n        if self.moving_left and self.rect.left > 0:\n            self.x -= self.settings.ship_speed\n\n        # Update rect object from self.x.\n        self.rect.x = self.x\n\n    def blitme(self):\n        \"\"\"Draw the ship at its current location.\"\"\"\n        self.screen.blit(self.image, self.rect)\n\n    def center_ship(self):\n        \"\"\"Center the ship on the screen.\"\"\"\n        self.rect.midbottom = self.screen_rect.midbottom\n        self.x = float(self.rect.x)\n"}},"14-5":{"ch":14,"entry":"alien_invasion.py","mode":"run","reason":null,"files":{"alien.py":"import pygame\nfrom pygame.sprite import Sprite\n \nclass Alien(Sprite):\n    \"\"\"A class to represent a single alien in the fleet.\"\"\"\n\n    def __init__(self, ai_game):\n        \"\"\"Initialize the alien and set its starting position.\"\"\"\n        super().__init__()\n        self.screen = ai_game.screen\n        self.settings = ai_game.settings\n\n        # Load the alien image and set its rect attribute.\n        self.image = pygame.image.load('images/alien.bmp')\n        self.rect = self.image.get_rect()\n\n        # Start each new alien near the top left of the screen.\n        self.rect.x = self.rect.width\n        self.rect.y = self.rect.height\n\n        # Store the alien's exact horizontal position.\n        self.x = float(self.rect.x)\n\n    def check_edges(self):\n        \"\"\"Return True if alien is at edge of screen.\"\"\"\n        screen_rect = self.screen.get_rect()\n        if self.rect.right >= screen_rect.right or self.rect.left <= 0:\n            return True\n\n    def update(self):\n        \"\"\"Move the alien right or left.\"\"\"\n        self.x += (self.settings.alien_speed *\n                        self.settings.fleet_direction)\n        self.rect.x = self.x\n","alien_invasion.py":"import sys\nfrom time import sleep\nimport json\nfrom pathlib import Path\n\nimport pygame\n\nfrom settings import Settings\nfrom game_stats import GameStats\nfrom scoreboard import Scoreboard\nfrom button import Button\nfrom ship import Ship\nfrom bullet import Bullet\nfrom alien import Alien\n\n\nclass AlienInvasion:\n    \"\"\"Overall class to manage game assets and behavior.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game, and create game resources.\"\"\"\n        pygame.init()\n        self.clock = pygame.time.Clock()\n        self.settings = Settings()\n\n        self.screen = pygame.display.set_mode(\n                (self.settings.screen_width, self.settings.screen_height))\n        pygame.display.set_caption(\"Alien Invasion\")\n\n        # Create an instance to store game statistics,\n        #   and create a scoreboard.\n        self.stats = GameStats(self)\n        self.sb = Scoreboard(self)\n\n        self.ship = Ship(self)\n        self.bullets = pygame.sprite.Group()\n        self.aliens = pygame.sprite.Group()\n\n        self._create_fleet()\n\n        # Make the Play button.\n        self.play_button = Button(self, \"Play\")\n\n        # Start game in an inactive state.\n        self.game_active = False\n\n    def run_game(self):\n        \"\"\"Start the main loop for the game.\"\"\"\n        while True:\n            self._check_events()\n\n            if self.game_active:\n                self.ship.update()\n                self._update_bullets()\n                self._update_aliens()\n\n            self._update_screen()\n            self.clock.tick(60)\n\n    def _check_events(self):\n        \"\"\"Respond to keypresses and mouse events.\"\"\"\n        for event in pygame.event.get():\n            if event.type == pygame.QUIT:\n                self._close_game()\n            elif event.type == pygame.KEYDOWN:\n                self._check_keydown_events(event)\n            elif event.type == pygame.KEYUP:\n                self._check_keyup_events(event)\n            elif event.type == pygame.MOUSEBUTTONDOWN:\n                mouse_pos = pygame.mouse.get_pos()\n                self._check_play_button(mouse_pos)\n\n    def _check_play_button(self, mouse_pos):\n        \"\"\"Start a new game when the player clicks Play.\"\"\"\n        button_clicked = self.play_button.rect.collidepoint(mouse_pos)\n        if button_clicked and not self.game_active:\n            self._start_game()\n\n    def _start_game(self):\n        \"\"\"Start a new game.\"\"\"\n        # Reset the game settings.\n        self.settings.initialize_dynamic_settings()\n\n        # Reset the game statistics.\n        self.stats.reset_stats()\n        self.game_active = True\n        self.sb.prep_score()\n        self.sb.prep_level()\n        self.sb.prep_ships()\n\n        # Get rid of any remaining aliens and bullets.\n        self.aliens.empty()\n        self.bullets.empty()\n        \n        # Create a new fleet and center the ship.\n        self._create_fleet()\n        self.ship.center_ship()\n\n        # Hide the mouse cursor.\n        pygame.mouse.set_visible(False)\n\n    def _check_keydown_events(self, event):\n        \"\"\"Respond to keypresses.\"\"\"\n        if event.key == pygame.K_RIGHT:\n            self.ship.moving_right = True\n        elif event.key == pygame.K_LEFT:\n            self.ship.moving_left = True\n        elif event.key == pygame.K_q:\n            self._close_game()\n        elif event.key == pygame.K_SPACE:\n            self._fire_bullet()\n        elif event.key == pygame.K_p and not self.game_active:\n            self._start_game()\n\n    def _check_keyup_events(self, event):\n        \"\"\"Respond to key releases.\"\"\"\n        if event.key == pygame.K_RIGHT:\n            self.ship.moving_right = False\n        elif event.key == pygame.K_LEFT:\n            self.ship.moving_left = False\n\n    def _fire_bullet(self):\n        \"\"\"Create a new bullet and add it to the bullets group.\"\"\"\n        if len(self.bullets) < self.settings.bullets_allowed:\n            new_bullet = Bullet(self)\n            self.bullets.add(new_bullet)\n\n    def _update_bullets(self):\n        \"\"\"Update position of bullets and get rid of old bullets.\"\"\"\n        # Update bullet positions.\n        self.bullets.update()\n\n        # Get rid of bullets that have disappeared.\n        for bullet in self.bullets.copy():\n            if bullet.rect.bottom <= 0:\n                 self.bullets.remove(bullet)\n\n        self._check_bullet_alien_collisions()\n\n    def _check_bullet_alien_collisions(self):\n        \"\"\"Respond to bullet-alien collisions.\"\"\"\n        # Remove any bullets and aliens that have collided.\n        collisions = pygame.sprite.groupcollide(\n                self.bullets, self.aliens, True, True)\n\n        if collisions:\n            for aliens in collisions.values():\n                self.stats.score += self.settings.alien_points * len(aliens)\n            self.sb.prep_score()\n            self.sb.check_high_score()\n\n        if not self.aliens:\n            # Destroy existing bullets and create new fleet.\n            self.bullets.empty()\n            self._create_fleet()\n            self.settings.increase_speed()\n\n            # Increase level.\n            self.stats.level += 1\n            self.sb.prep_level()\n\n    def _update_aliens(self):\n        \"\"\"\n        Check if the fleet is at an edge,\n          then update the positions of all aliens in the fleet.\n        \"\"\"\n        self._check_fleet_edges()\n        self.aliens.update()\n\n        # Look for alien-ship collisions.\n        if pygame.sprite.spritecollideany(self.ship, self.aliens):\n            self._ship_hit()\n\n        # Look for aliens hitting the bottom of the screen.\n        self._check_aliens_bottom()\n\n    def _check_aliens_bottom(self):\n        \"\"\"Check if any aliens have reached the bottom of the screen.\"\"\"\n        screen_rect = self.screen.get_rect()\n        for alien in self.aliens.sprites():\n            if alien.rect.bottom >= screen_rect.bottom:\n                # Treat this the same as if the ship got hit.\n                self._ship_hit()\n                break\n\n    def _ship_hit(self):\n        \"\"\"Respond to the ship being hit by an alien.\"\"\"\n        if self.stats.ships_left > 0:\n            # Decrement ships_left, and update scoreboard.\n            self.stats.ships_left -= 1\n            self.sb.prep_ships()\n            \n            # Get rid of any remaining aliens and bullets.\n            self.aliens.empty()\n            self.bullets.empty()\n            \n            # Create a new fleet and center the ship.\n            self._create_fleet()\n            self.ship.center_ship()\n            \n            # Pause.\n            sleep(0.5)\n        else:\n            self.game_active = False\n            pygame.mouse.set_visible(True)\n\n    def _create_fleet(self):\n        \"\"\"Create the fleet of aliens.\"\"\"\n        # Create an alien and find the number of aliens in a row.\n        # Spacing between each alien is equal to one alien width.\n        alien = Alien(self)\n        alien_width, alien_height = alien.rect.size\n        available_space_x = self.settings.screen_width - (2 * alien_width)\n        number_aliens_x = available_space_x // (2 * alien_width)\n        \n        # Determine the number of rows of aliens that fit on the screen.\n        ship_height = self.ship.rect.height\n        available_space_y = (self.settings.screen_height -\n                                (3 * alien_height) - ship_height)\n        number_rows = available_space_y // (2 * alien_height)\n        \n        # Create the full fleet of aliens.\n        for row_number in range(number_rows):\n            for alien_number in range(number_aliens_x):\n                self._create_alien(alien_number, row_number)\n\n    def _create_alien(self, alien_number, row_number):\n        \"\"\"Create an alien and place it in the row.\"\"\"\n        alien = Alien(self)\n        alien_width, alien_height = alien.rect.size\n        alien.x = alien_width + 2 * alien_width * alien_number\n        alien.rect.x = alien.x\n        alien.rect.y = alien.rect.height + 2 * alien.rect.height * row_number\n        self.aliens.add(alien)\n\n    def _check_fleet_edges(self):\n        \"\"\"Respond appropriately if any aliens have reached an edge.\"\"\"\n        for alien in self.aliens.sprites():\n            if alien.check_edges():\n                self._change_fleet_direction()\n                break\n            \n    def _change_fleet_direction(self):\n        \"\"\"Drop the entire fleet and change the fleet's direction.\"\"\"\n        for alien in self.aliens.sprites():\n            alien.rect.y += self.settings.fleet_drop_speed\n        self.settings.fleet_direction *= -1\n\n    def _update_screen(self):\n        \"\"\"Update images on the screen, and flip to the new screen.\"\"\"\n        self.screen.fill(self.settings.bg_color)\n        self.ship.blitme()\n        for bullet in self.bullets.sprites():\n            bullet.draw_bullet()\n        self.aliens.draw(self.screen)\n\n        # Draw the score information.\n        self.sb.show_score()\n\n        # Draw the play button if the game is inactive.\n        if not self.game_active:\n            self.play_button.draw_button()\n\n        pygame.display.flip()\n\n    def _close_game(self):\n        \"\"\"Save high score and exit.\"\"\"\n        saved_high_score = self.stats.get_saved_high_score()\n        if self.stats.high_score > saved_high_score:\n            path = Path('high_score.json')\n            contents = json.dumps(self.stats.high_score)\n            path.write_text(contents)\n        \n        sys.exit()\n\n\nif __name__ == '__main__':\n    # Make a game instance, and run the game.\n    ai = AlienInvasion()\n    ai.run_game()\n","bullet.py":"import pygame\nfrom pygame.sprite import Sprite\n \nclass Bullet(Sprite):\n    \"\"\"A class to manage bullets fired from the ship\"\"\"\n\n    def __init__(self, ai_game):\n        \"\"\"Create a bullet object at the ship's current position.\"\"\"\n        super().__init__()\n        self.screen = ai_game.screen\n        self.settings = ai_game.settings\n        self.color = self.settings.bullet_color\n\n        # Create a bullet rect at (0, 0) and then set correct position.\n        self.rect = pygame.Rect(0, 0, self.settings.bullet_width,\n            self.settings.bullet_height)\n        self.rect.midtop = ai_game.ship.rect.midtop\n        \n        # Store the bullet's position as a decimal value.\n        self.y = float(self.rect.y)\n\n    def update(self):\n        \"\"\"Move the bullet up the screen.\"\"\"\n        # Update the decimal position of the bullet.\n        self.y -= self.settings.bullet_speed\n        # Update the rect position.\n        self.rect.y = self.y\n\n    def draw_bullet(self):\n        \"\"\"Draw the bullet to the screen.\"\"\"\n        pygame.draw.rect(self.screen, self.color, self.rect)\n","button.py":"import pygame.font\n \nclass Button:\n \n    def __init__(self, ai_game, msg):\n        \"\"\"Initialize button attributes.\"\"\"\n        self.screen = ai_game.screen\n        self.screen_rect = self.screen.get_rect()\n        \n        # Set the dimensions and properties of the button.\n        self.width, self.height = 200, 50\n        self.button_color = (0, 135, 0)\n        self.text_color = (255, 255, 255)\n        self.font = pygame.font.SysFont(None, 48)\n        \n        # Build the button's rect object and center it.\n        self.rect = pygame.Rect(0, 0, self.width, self.height)\n        self.rect.center = self.screen_rect.center\n        \n        # The button message needs to be prepped only once.\n        self._prep_msg(msg)\n\n    def _prep_msg(self, msg):\n        \"\"\"Turn msg into a rendered image and center text on the button.\"\"\"\n        self.msg_image = self.font.render(msg, True, self.text_color,\n                self.button_color)\n        self.msg_image_rect = self.msg_image.get_rect()\n        self.msg_image_rect.center = self.rect.center\n\n    def draw_button(self):\n        # Draw blank button and then draw message.\n        self.screen.fill(self.button_color, self.rect)\n        self.screen.blit(self.msg_image, self.msg_image_rect)","game_stats.py":"import json\nfrom pathlib import Path\n\nclass GameStats:\n    \"\"\"Track statistics for Alien Invasion.\"\"\"\n    \n    def __init__(self, ai_game):\n        \"\"\"Initialize statistics.\"\"\"\n        self.settings = ai_game.settings\n        self.reset_stats()\n\n        # High score should never be reset.\n        self.high_score = self.get_saved_high_score()\n\n    def get_saved_high_score(self):\n        \"\"\"Gets high score from file, if it exists.\"\"\"\n        path = Path('high_score.json')\n        try:\n            contents = path.read_text()\n            high_score = json.loads(contents)\n            return high_score\n        except FileNotFoundError:\n            return 0\n\n    def reset_stats(self):\n        \"\"\"Initialize statistics that can change during the game.\"\"\"\n        self.ships_left = self.settings.ship_limit\n        self.score = 0\n        self.level = 1","images/alien.bmp":{"b64":""},"images/ship.bmp":{"b64":""},"scoreboard.py":"import pygame.font\nfrom pygame.sprite import Group\n \nfrom ship import Ship\n\nclass Scoreboard:\n    \"\"\"A class to report scoring information.\"\"\"\n\n    def __init__(self, ai_game):\n        \"\"\"Initialize scorekeeping attributes.\"\"\"\n        self.ai_game = ai_game\n        self.screen = ai_game.screen\n        self.screen_rect = self.screen.get_rect()\n        self.settings = ai_game.settings\n        self.stats = ai_game.stats\n        \n        # Font settings for scoring information.\n        self.text_color = (30, 30, 30)\n        self.font = pygame.font.SysFont(None, 48)\n\n        # Prepare the initial score images.\n        self.prep_score()\n        self.prep_high_score()\n        self.prep_level()\n        self.prep_ships()\n\n    def prep_score(self):\n        \"\"\"Turn the score into a rendered image.\"\"\"\n        rounded_score = round(self.stats.score, -1)\n        score_str = \"{:,}\".format(rounded_score)\n        self.score_image = self.font.render(score_str, True,\n                self.text_color, self.settings.bg_color)\n        \n        # Display the score at the top right of the screen.\n        self.score_rect = self.score_image.get_rect()\n        self.score_rect.right = self.screen_rect.right - 20\n        self.score_rect.top = 20\n\n    def prep_high_score(self):\n        \"\"\"Turn the high score into a rendered image.\"\"\"\n        high_score = round(self.stats.high_score, -1)\n        high_score_str = \"{:,}\".format(high_score)\n        self.high_score_image = self.font.render(high_score_str, True,\n                self.text_color, self.settings.bg_color)\n            \n        # Center the high score at the top of the screen.\n        self.high_score_rect = self.high_score_image.get_rect()\n        self.high_score_rect.centerx = self.screen_rect.centerx\n        self.high_score_rect.top = self.score_rect.top\n\n    def prep_level(self):\n        \"\"\"Turn the level into a rendered image.\"\"\"\n        level_str = str(self.stats.level)\n        self.level_image = self.font.render(level_str, True,\n                self.text_color, self.settings.bg_color)\n    \n        # Position the level below the score.\n        self.level_rect = self.level_image.get_rect()\n        self.level_rect.right = self.score_rect.right\n        self.level_rect.top = self.score_rect.bottom + 10\n\n    def prep_ships(self):\n        \"\"\"Show how many ships are left.\"\"\"\n        self.ships = Group()\n        for ship_number in range(self.stats.ships_left):\n            ship = Ship(self.ai_game)\n            ship.rect.x = 10 + ship_number * ship.rect.width\n            ship.rect.y = 10\n            self.ships.add(ship)\n\n    def check_high_score(self):\n        \"\"\"Check to see if there's a new high score.\"\"\"\n        if self.stats.score > self.stats.high_score:\n            self.stats.high_score = self.stats.score\n            self.prep_high_score()\n\n    def show_score(self):\n        \"\"\"Draw scores, level, and ships to the screen.\"\"\"\n        self.screen.blit(self.score_image, self.score_rect)\n        self.screen.blit(self.high_score_image, self.high_score_rect)\n        self.screen.blit(self.level_image, self.level_rect)\n        self.ships.draw(self.screen)\n","settings.py":"class Settings:\n    \"\"\"A class to store all settings for Alien Invasion.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game's static settings.\"\"\"\n        # Screen settings\n        self.screen_width = 1200\n        self.screen_height = 800\n        self.bg_color = (230, 230, 230)\n\n        # Ship settings\n        self.ship_limit = 3\n\n        # Bullet settings\n        self.bullet_width = 3\n        self.bullet_height = 15\n        self.bullet_color = (60, 60, 60)\n        self.bullets_allowed = 3\n\n        # Alien settings\n        self.fleet_drop_speed = 10\n\n        # How quickly the game speeds up\n        self.speedup_scale = 1.1\n        # How quickly the alien point values increase\n        self.score_scale = 1.5\n\n        self.initialize_dynamic_settings()\n\n    def initialize_dynamic_settings(self):\n        \"\"\"Initialize settings that change throughout the game.\"\"\"\n        self.ship_speed = 1.5\n        self.bullet_speed = 3.0\n        self.alien_speed = 1.0\n\n        # fleet_direction of 1 represents right; -1 represents left.\n        self.fleet_direction = 1\n\n        # Scoring\n        self.alien_points = 50\n\n    def increase_speed(self):\n        \"\"\"Increase speed settings and alien point values.\"\"\"\n        self.ship_speed *= self.speedup_scale\n        self.bullet_speed *= self.speedup_scale\n        self.alien_speed *= self.speedup_scale\n\n        self.alien_points = int(self.alien_points * self.score_scale)\n","ship.py":"import pygame\n \nfrom pygame.sprite import Sprite\n \nclass Ship(Sprite):\n    \"\"\"A class to manage the ship.\"\"\"\n \n    def __init__(self, ai_game):\n        \"\"\"Initialize the ship and set its starting position.\"\"\"\n        super().__init__()\n        self.screen = ai_game.screen\n        self.settings = ai_game.settings\n        self.screen_rect = ai_game.screen.get_rect()\n\n        # Load the ship image and get its rect.\n        self.image = pygame.image.load('images/ship.bmp')\n        self.rect = self.image.get_rect()\n\n        # Start each new ship at the bottom center of the screen.\n        self.rect.midbottom = self.screen_rect.midbottom\n\n        # Store a decimal value for the ship's horizontal position.\n        self.x = float(self.rect.x)\n\n        # Movement flags\n        self.moving_right = False\n        self.moving_left = False\n\n    def update(self):\n        \"\"\"Update the ship's position based on movement flags.\"\"\"\n        # Update the ship's x value, not the rect.\n        if self.moving_right and self.rect.right < self.screen_rect.right:\n            self.x += self.settings.ship_speed\n        if self.moving_left and self.rect.left > 0:\n            self.x -= self.settings.ship_speed\n\n        # Update rect object from self.x.\n        self.rect.x = self.x\n\n    def blitme(self):\n        \"\"\"Draw the ship at its current location.\"\"\"\n        self.screen.blit(self.image, self.rect)\n\n    def center_ship(self):\n        \"\"\"Center the ship on the screen.\"\"\"\n        self.rect.midbottom = self.screen_rect.midbottom\n        self.x = float(self.rect.x)\n"}},"14-6":{"ch":14,"entry":"alien_invasion.py","mode":"run","reason":null,"files":{"alien.py":"import pygame\nfrom pygame.sprite import Sprite\n \nclass Alien(Sprite):\n    \"\"\"A class to represent a single alien in the fleet.\"\"\"\n\n    def __init__(self, ai_game):\n        \"\"\"Initialize the alien and set its starting position.\"\"\"\n        super().__init__()\n        self.screen = ai_game.screen\n        self.settings = ai_game.settings\n\n        # Load the alien image and set its rect attribute.\n        self.image = pygame.image.load('images/alien.bmp')\n        self.rect = self.image.get_rect()\n\n        # Start each new alien near the top left of the screen.\n        self.rect.x = self.rect.width\n        self.rect.y = self.rect.height\n\n        # Store the alien's exact horizontal position.\n        self.x = float(self.rect.x)\n\n    def check_edges(self):\n        \"\"\"Return True if alien is at edge of screen.\"\"\"\n        screen_rect = self.screen.get_rect()\n        if self.rect.right >= screen_rect.right or self.rect.left <= 0:\n            return True\n\n    def update(self):\n        \"\"\"Move the alien right or left.\"\"\"\n        self.x += (self.settings.alien_speed *\n                        self.settings.fleet_direction)\n        self.rect.x = self.x\n","alien_invasion.py":"import sys\nfrom time import sleep\nimport json\nfrom pathlib import Path\n\nimport pygame\n\nfrom settings import Settings\nfrom game_stats import GameStats\nfrom scoreboard import Scoreboard\nfrom button import Button\nfrom ship import Ship\nfrom bullet import Bullet\nfrom alien import Alien\n\n\nclass AlienInvasion:\n    \"\"\"Overall class to manage game assets and behavior.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game, and create game resources.\"\"\"\n        pygame.init()\n        self.clock = pygame.time.Clock()\n        self.settings = Settings()\n\n        self.screen = pygame.display.set_mode(\n                (self.settings.screen_width, self.settings.screen_height))\n        pygame.display.set_caption(\"Alien Invasion\")\n\n        # Create an instance to store game statistics,\n        #   and create a scoreboard.\n        self.stats = GameStats(self)\n        self.sb = Scoreboard(self)\n\n        self.ship = Ship(self)\n        self.bullets = pygame.sprite.Group()\n        self.aliens = pygame.sprite.Group()\n\n        self._create_fleet()\n\n        # Make the Play button.\n        self.play_button = Button(self, \"Play\")\n\n        # Start game in an inactive state.\n        self.game_active = False\n\n    def run_game(self):\n        \"\"\"Start the main loop for the game.\"\"\"\n        while True:\n            self._check_events()\n\n            if self.game_active:\n                self.ship.update()\n                self._update_bullets()\n                self._update_aliens()\n\n            self._update_screen()\n            self.clock.tick(60)\n\n    def _check_events(self):\n        \"\"\"Respond to keypresses and mouse events.\"\"\"\n        for event in pygame.event.get():\n            if event.type == pygame.QUIT:\n                self._close_game()\n            elif event.type == pygame.KEYDOWN:\n                self._check_keydown_events(event)\n            elif event.type == pygame.KEYUP:\n                self._check_keyup_events(event)\n            elif event.type == pygame.MOUSEBUTTONDOWN:\n                mouse_pos = pygame.mouse.get_pos()\n                self._check_play_button(mouse_pos)\n\n    def _check_play_button(self, mouse_pos):\n        \"\"\"Start a new game when the player clicks Play.\"\"\"\n        button_clicked = self.play_button.rect.collidepoint(mouse_pos)\n        if button_clicked and not self.game_active:\n            self._start_game()\n\n    def _start_game(self):\n        \"\"\"Start a new game.\"\"\"\n        # Reset the game settings.\n        self.settings.initialize_dynamic_settings()\n\n        # Reset the game statistics.\n        self.stats.reset_stats()\n        self.game_active = True\n        self.sb.prep_images()\n\n        # Get rid of any remaining aliens and bullets.\n        self.aliens.empty()\n        self.bullets.empty()\n        \n        # Create a new fleet and center the ship.\n        self._create_fleet()\n        self.ship.center_ship()\n\n        # Hide the mouse cursor.\n        pygame.mouse.set_visible(False)\n\n    def _check_keydown_events(self, event):\n        \"\"\"Respond to keypresses.\"\"\"\n        if event.key == pygame.K_RIGHT:\n            self.ship.moving_right = True\n        elif event.key == pygame.K_LEFT:\n            self.ship.moving_left = True\n        elif event.key == pygame.K_q:\n            self._close_game()\n        elif event.key == pygame.K_SPACE:\n            self._fire_bullet()\n        elif event.key == pygame.K_p and not self.game_active:\n            self._start_game()\n\n    def _check_keyup_events(self, event):\n        \"\"\"Respond to key releases.\"\"\"\n        if event.key == pygame.K_RIGHT:\n            self.ship.moving_right = False\n        elif event.key == pygame.K_LEFT:\n            self.ship.moving_left = False\n\n    def _fire_bullet(self):\n        \"\"\"Create a new bullet and add it to the bullets group.\"\"\"\n        if len(self.bullets) < self.settings.bullets_allowed:\n            new_bullet = Bullet(self)\n            self.bullets.add(new_bullet)\n\n    def _update_bullets(self):\n        \"\"\"Update position of bullets and get rid of old bullets.\"\"\"\n        # Update bullet positions.\n        self.bullets.update()\n\n        # Get rid of bullets that have disappeared.\n        for bullet in self.bullets.copy():\n            if bullet.rect.bottom <= 0:\n                 self.bullets.remove(bullet)\n\n        self._check_bullet_alien_collisions()\n\n    def _check_bullet_alien_collisions(self):\n        \"\"\"Respond to bullet-alien collisions.\"\"\"\n        # Remove any bullets and aliens that have collided.\n        collisions = pygame.sprite.groupcollide(\n                self.bullets, self.aliens, True, True)\n\n        if collisions:\n            for aliens in collisions.values():\n                self.stats.score += self.settings.alien_points * len(aliens)\n            self.sb.prep_score()\n            self.sb.check_high_score()\n\n        if not self.aliens:\n            self._start_new_level()\n\n    def _start_new_level(self):\n        \"\"\"Start a new level, after the fleet has been cleared.\"\"\"\n        # Destroy existing bullets and create new fleet.\n        self.bullets.empty()\n        self._create_fleet()\n        self.settings.increase_speed()\n\n        # Increase level.\n        self.stats.level += 1\n        self.sb.prep_level()\n\n    def _update_aliens(self):\n        \"\"\"\n        Check if the fleet is at an edge,\n          then update the positions of all aliens in the fleet.\n        \"\"\"\n        self._check_fleet_edges()\n        self.aliens.update()\n\n        # Look for alien-ship collisions.\n        if pygame.sprite.spritecollideany(self.ship, self.aliens):\n            self._ship_hit()\n\n        # Look for aliens hitting the bottom of the screen.\n        self._check_aliens_bottom()\n\n    def _check_aliens_bottom(self):\n        \"\"\"Check if any aliens have reached the bottom of the screen.\"\"\"\n        screen_rect = self.screen.get_rect()\n        for alien in self.aliens.sprites():\n            if alien.rect.bottom >= screen_rect.bottom:\n                # Treat this the same as if the ship got hit.\n                self._ship_hit()\n                break\n\n    def _ship_hit(self):\n        \"\"\"Respond to the ship being hit by an alien.\"\"\"\n        if self.stats.ships_left > 0:\n            # Decrement ships_left, and update scoreboard.\n            self.stats.ships_left -= 1\n            self.sb.prep_ships()\n            \n            # Get rid of any remaining aliens and bullets.\n            self.aliens.empty()\n            self.bullets.empty()\n            \n            # Create a new fleet and center the ship.\n            self._create_fleet()\n            self.ship.center_ship()\n            \n            # Pause.\n            sleep(0.5)\n        else:\n            self.game_active = False\n            pygame.mouse.set_visible(True)\n\n    def _create_fleet(self):\n        \"\"\"Create the fleet of aliens.\"\"\"\n        # Create an alien and find the number of aliens in a row.\n        # Spacing between each alien is equal to one alien width.\n        alien = Alien(self)\n        alien_width, alien_height = alien.rect.size\n        available_space_x = self.settings.screen_width - (2 * alien_width)\n        number_aliens_x = available_space_x // (2 * alien_width)\n        \n        # Determine the number of rows of aliens that fit on the screen.\n        ship_height = self.ship.rect.height\n        available_space_y = (self.settings.screen_height -\n                                (3 * alien_height) - ship_height)\n        number_rows = available_space_y // (2 * alien_height)\n        \n        # Create the full fleet of aliens.\n        for row_number in range(number_rows):\n            for alien_number in range(number_aliens_x):\n                self._create_alien(alien_number, row_number)\n\n    def _create_alien(self, alien_number, row_number):\n        \"\"\"Create an alien and place it in the row.\"\"\"\n        alien = Alien(self)\n        alien_width, alien_height = alien.rect.size\n        alien.x = alien_width + 2 * alien_width * alien_number\n        alien.rect.x = alien.x\n        alien.rect.y = alien.rect.height + 2 * alien.rect.height * row_number\n        self.aliens.add(alien)\n\n    def _check_fleet_edges(self):\n        \"\"\"Respond appropriately if any aliens have reached an edge.\"\"\"\n        for alien in self.aliens.sprites():\n            if alien.check_edges():\n                self._change_fleet_direction()\n                break\n            \n    def _change_fleet_direction(self):\n        \"\"\"Drop the entire fleet and change the fleet's direction.\"\"\"\n        for alien in self.aliens.sprites():\n            alien.rect.y += self.settings.fleet_drop_speed\n        self.settings.fleet_direction *= -1\n\n    def _update_screen(self):\n        \"\"\"Update images on the screen, and flip to the new screen.\"\"\"\n        self.screen.fill(self.settings.bg_color)\n        self.ship.blitme()\n        for bullet in self.bullets.sprites():\n            bullet.draw_bullet()\n        self.aliens.draw(self.screen)\n\n        # Draw the score information.\n        self.sb.show_score()\n\n        # Draw the play button if the game is inactive.\n        if not self.game_active:\n            self.play_button.draw_button()\n\n        pygame.display.flip()\n\n    def _close_game(self):\n        \"\"\"Save high score and exit.\"\"\"\n        saved_high_score = self.stats.get_saved_high_score()\n        if self.stats.high_score > saved_high_score:\n            path = Path('high_score.json')\n            contents = json.dumps(self.stats.high_score)\n            path.write_text(contents)\n        \n        sys.exit()\n\n\nif __name__ == '__main__':\n    # Make a game instance, and run the game.\n    ai = AlienInvasion()\n    ai.run_game()\n","bullet.py":"import pygame\nfrom pygame.sprite import Sprite\n \nclass Bullet(Sprite):\n    \"\"\"A class to manage bullets fired from the ship\"\"\"\n\n    def __init__(self, ai_game):\n        \"\"\"Create a bullet object at the ship's current position.\"\"\"\n        super().__init__()\n        self.screen = ai_game.screen\n        self.settings = ai_game.settings\n        self.color = self.settings.bullet_color\n\n        # Create a bullet rect at (0, 0) and then set correct position.\n        self.rect = pygame.Rect(0, 0, self.settings.bullet_width,\n            self.settings.bullet_height)\n        self.rect.midtop = ai_game.ship.rect.midtop\n        \n        # Store the bullet's position as a decimal value.\n        self.y = float(self.rect.y)\n\n    def update(self):\n        \"\"\"Move the bullet up the screen.\"\"\"\n        # Update the decimal position of the bullet.\n        self.y -= self.settings.bullet_speed\n        # Update the rect position.\n        self.rect.y = self.y\n\n    def draw_bullet(self):\n        \"\"\"Draw the bullet to the screen.\"\"\"\n        pygame.draw.rect(self.screen, self.color, self.rect)\n","button.py":"import pygame.font\n \nclass Button:\n \n    def __init__(self, ai_game, msg):\n        \"\"\"Initialize button attributes.\"\"\"\n        self.screen = ai_game.screen\n        self.screen_rect = self.screen.get_rect()\n        \n        # Set the dimensions and properties of the button.\n        self.width, self.height = 200, 50\n        self.button_color = (0, 135, 0)\n        self.text_color = (255, 255, 255)\n        self.font = pygame.font.SysFont(None, 48)\n        \n        # Build the button's rect object and center it.\n        self.rect = pygame.Rect(0, 0, self.width, self.height)\n        self.rect.center = self.screen_rect.center\n        \n        # The button message needs to be prepped only once.\n        self._prep_msg(msg)\n\n    def _prep_msg(self, msg):\n        \"\"\"Turn msg into a rendered image and center text on the button.\"\"\"\n        self.msg_image = self.font.render(msg, True, self.text_color,\n                self.button_color)\n        self.msg_image_rect = self.msg_image.get_rect()\n        self.msg_image_rect.center = self.rect.center\n\n    def draw_button(self):\n        # Draw blank button and then draw message.\n        self.screen.fill(self.button_color, self.rect)\n        self.screen.blit(self.msg_image, self.msg_image_rect)","game_stats.py":"import json\nfrom pathlib import Path\n\nclass GameStats:\n    \"\"\"Track statistics for Alien Invasion.\"\"\"\n    \n    def __init__(self, ai_game):\n        \"\"\"Initialize statistics.\"\"\"\n        self.settings = ai_game.settings\n        self.reset_stats()\n\n        # High score should never be reset.\n        self.high_score = self.get_saved_high_score()\n\n    def get_saved_high_score(self):\n        \"\"\"Gets high score from file, if it exists.\"\"\"\n        path = Path('high_score.json')\n        try:\n            contents = path.read_text()\n            high_score = json.loads(contents)\n            return high_score\n        except FileNotFoundError:\n            return 0\n\n    def reset_stats(self):\n        \"\"\"Initialize statistics that can change during the game.\"\"\"\n        self.ships_left = self.settings.ship_limit\n        self.score = 0\n        self.level = 1","high_score.json":"4500","images/alien.bmp":{"b64":""},"images/ship.bmp":{"b64":""},"scoreboard.py":"import pygame.font\nfrom pygame.sprite import Group\n \nfrom ship import Ship\n\nclass Scoreboard:\n    \"\"\"A class to report scoring information.\"\"\"\n\n    def __init__(self, ai_game):\n        \"\"\"Initialize scorekeeping attributes.\"\"\"\n        self.ai_game = ai_game\n        self.screen = ai_game.screen\n        self.screen_rect = self.screen.get_rect()\n        self.settings = ai_game.settings\n        self.stats = ai_game.stats\n        \n        # Font settings for scoring information.\n        self.text_color = (30, 30, 30)\n        self.font = pygame.font.SysFont(None, 48)\n\n        self.prep_images()\n        \n\n    def prep_images(self):\n        \"\"\"Prepare all of the initial score images.\"\"\"\n        self.prep_score()\n        self.prep_high_score()\n        self.prep_level()\n        self.prep_ships()\n\n    def prep_score(self):\n        \"\"\"Turn the score into a rendered image.\"\"\"\n        rounded_score = round(self.stats.score, -1)\n        score_str = \"{:,}\".format(rounded_score)\n        self.score_image = self.font.render(score_str, True,\n                self.text_color, self.settings.bg_color)\n        \n        # Display the score at the top right of the screen.\n        self.score_rect = self.score_image.get_rect()\n        self.score_rect.right = self.screen_rect.right - 20\n        self.score_rect.top = 20\n\n    def prep_high_score(self):\n        \"\"\"Turn the high score into a rendered image.\"\"\"\n        high_score = round(self.stats.high_score, -1)\n        high_score_str = \"{:,}\".format(high_score)\n        self.high_score_image = self.font.render(high_score_str, True,\n                self.text_color, self.settings.bg_color)\n            \n        # Center the high score at the top of the screen.\n        self.high_score_rect = self.high_score_image.get_rect()\n        self.high_score_rect.centerx = self.screen_rect.centerx\n        self.high_score_rect.top = self.score_rect.top\n\n    def prep_level(self):\n        \"\"\"Turn the level into a rendered image.\"\"\"\n        level_str = str(self.stats.level)\n        self.level_image = self.font.render(level_str, True,\n                self.text_color, self.settings.bg_color)\n    \n        # Position the level below the score.\n        self.level_rect = self.level_image.get_rect()\n        self.level_rect.right = self.score_rect.right\n        self.level_rect.top = self.score_rect.bottom + 10\n\n    def prep_ships(self):\n        \"\"\"Show how many ships are left.\"\"\"\n        self.ships = Group()\n        for ship_number in range(self.stats.ships_left):\n            ship = Ship(self.ai_game)\n            ship.rect.x = 10 + ship_number * ship.rect.width\n            ship.rect.y = 10\n            self.ships.add(ship)\n\n    def check_high_score(self):\n        \"\"\"Check to see if there's a new high score.\"\"\"\n        if self.stats.score > self.stats.high_score:\n            self.stats.high_score = self.stats.score\n            self.prep_high_score()\n\n    def show_score(self):\n        \"\"\"Draw scores, level, and ships to the screen.\"\"\"\n        self.screen.blit(self.score_image, self.score_rect)\n        self.screen.blit(self.high_score_image, self.high_score_rect)\n        self.screen.blit(self.level_image, self.level_rect)\n        self.ships.draw(self.screen)\n","settings.py":"class Settings:\n    \"\"\"A class to store all settings for Alien Invasion.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game's static settings.\"\"\"\n        # Screen settings\n        self.screen_width = 1200\n        self.screen_height = 800\n        self.bg_color = (230, 230, 230)\n\n        # Ship settings\n        self.ship_limit = 3\n\n        # Bullet settings\n        self.bullet_width = 3000\n        self.bullet_height = 15\n        self.bullet_color = (60, 60, 60)\n        self.bullets_allowed = 3\n\n        # Alien settings\n        self.fleet_drop_speed = 10\n\n        # How quickly the game speeds up\n        self.speedup_scale = 1.1\n        # How quickly the alien point values increase\n        self.score_scale = 1.5\n\n        self.initialize_dynamic_settings()\n\n    def initialize_dynamic_settings(self):\n        \"\"\"Initialize settings that change throughout the game.\"\"\"\n        self.ship_speed = 1.5\n        self.bullet_speed = 3.0\n        self.alien_speed = 1.0\n\n        # fleet_direction of 1 represents right; -1 represents left.\n        self.fleet_direction = 1\n\n        # Scoring\n        self.alien_points = 50\n\n    def increase_speed(self):\n        \"\"\"Increase speed settings and alien point values.\"\"\"\n        self.ship_speed *= self.speedup_scale\n        self.bullet_speed *= self.speedup_scale\n        self.alien_speed *= self.speedup_scale\n\n        self.alien_points = int(self.alien_points * self.score_scale)\n","ship.py":"import pygame\n \nfrom pygame.sprite import Sprite\n \nclass Ship(Sprite):\n    \"\"\"A class to manage the ship.\"\"\"\n \n    def __init__(self, ai_game):\n        \"\"\"Initialize the ship and set its starting position.\"\"\"\n        super().__init__()\n        self.screen = ai_game.screen\n        self.settings = ai_game.settings\n        self.screen_rect = ai_game.screen.get_rect()\n\n        # Load the ship image and get its rect.\n        self.image = pygame.image.load('images/ship.bmp')\n        self.rect = self.image.get_rect()\n\n        # Start each new ship at the bottom center of the screen.\n        self.rect.midbottom = self.screen_rect.midbottom\n\n        # Store a decimal value for the ship's horizontal position.\n        self.x = float(self.rect.x)\n\n        # Movement flags\n        self.moving_right = False\n        self.moving_left = False\n\n    def update(self):\n        \"\"\"Update the ship's position based on movement flags.\"\"\"\n        # Update the ship's x value, not the rect.\n        if self.moving_right and self.rect.right < self.screen_rect.right:\n            self.x += self.settings.ship_speed\n        if self.moving_left and self.rect.left > 0:\n            self.x -= self.settings.ship_speed\n\n        # Update rect object from self.x.\n        self.rect.x = self.x\n\n    def blitme(self):\n        \"\"\"Draw the ship at its current location.\"\"\"\n        self.screen.blit(self.image, self.rect)\n\n    def center_ship(self):\n        \"\"\"Center the ship on the screen.\"\"\"\n        self.rect.midbottom = self.screen_rect.midbottom\n        self.x = float(self.rect.x)\n"}},"14-8":{"ch":14,"entry":"sideways_shooter.py","mode":"run","reason":null,"files":{"sideways_shooter.py":"import sys\nfrom random import random\n\nimport pygame\n\nfrom settings import Settings\nfrom game_stats import GameStats\nfrom ship import Ship\nfrom bullet import Bullet\nfrom alien import Alien\nfrom button import Button\n\nclass SidewaysShooter:\n    \"\"\"Overall class to manage game assets and behavior.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game, and create game resources.\"\"\"\n        pygame.init()\n        self.clock = pygame.time.Clock()\n        self.settings = Settings()\n\n        self.screen = pygame.display.set_mode(\n                (self.settings.screen_width, self.settings.screen_height))\n        pygame.display.set_caption(\"Sideways Shooter\")\n\n        # Create an instance to store game statistics.\n        self.stats = GameStats(self)\n\n        self.ship = Ship(self)\n        self.bullets = pygame.sprite.Group()\n        self.aliens = pygame.sprite.Group()\n\n        # Make the Play button.\n        self.play_button = Button(self, \"Play\")\n\n        # Start game in an inactive state.\n        self.game_active = False\n\n    def run_game(self):\n        \"\"\"Start the main loop for the game.\"\"\"\n        while True:\n            self._check_events()\n\n            if self.game_active:\n                # Consider creating a new alien.\n                self._create_alien()\n\n                self.ship.update()\n                self._update_bullets()\n                self._update_aliens()\n            \n            self._update_screen()\n            self.clock.tick(60)\n\n    def _check_events(self):\n        \"\"\"Respond to keypresses and mouse events.\"\"\"\n        for event in pygame.event.get():\n            if event.type == pygame.QUIT:\n                sys.exit()\n            elif event.type == pygame.KEYDOWN:\n                self._check_keydown_events(event)\n            elif event.type == pygame.KEYUP:\n                self._check_keyup_events(event)\n            elif event.type == pygame.MOUSEBUTTONDOWN:\n                mouse_pos = pygame.mouse.get_pos()\n                self._check_play_button(mouse_pos)\n\n    def _check_play_button(self, mouse_pos):\n        \"\"\"Start a new game when the player clicks Play.\"\"\"\n        if (not self.game_active\n                and self.play_button.rect.collidepoint(mouse_pos)):\n            # Reset the game statistics.\n            self.stats.reset_stats()\n            self.game_active = True\n\n            # Get rid of any remaining aliens and bullets.\n            self.aliens.empty()\n            self.bullets.empty()\n\n            # Create a new fleet and center the ship.\n            self.ship.center_ship()\n\n    def _check_keydown_events(self, event):\n        \"\"\"Respond to keypresses.\"\"\"\n        if event.key == pygame.K_UP:\n            self.ship.moving_up = True\n        elif event.key == pygame.K_DOWN:\n            self.ship.moving_down = True\n        elif event.key == pygame.K_SPACE:\n            self._fire_bullet()\n        elif event.key == pygame.K_q:\n            sys.exit()\n\n    def _check_keyup_events(self, event):\n        \"\"\"Respond to key releases.\"\"\"\n        if event.key == pygame.K_UP:\n            self.ship.moving_up = False\n        elif event.key == pygame.K_DOWN:\n            self.ship.moving_down = False\n\n    def _fire_bullet(self):\n        \"\"\"Create a new bullet and add it to the bullets group.\"\"\"\n        if len(self.bullets) < self.settings.bullets_allowed:\n            new_bullet = Bullet(self)\n            self.bullets.add(new_bullet)\n\n    def _update_bullets(self):\n        \"\"\"Update position of bullets and get rid of old bullets.\"\"\"\n        # Update bullet positions.\n        self.bullets.update()\n\n        # Get rid of bullets that have disappeared.\n        for bullet in self.bullets.copy():\n            if bullet.rect.left >= self.screen.get_rect().right:\n                 self.bullets.remove(bullet)\n\n        self._check_bullet_alien_collisions()\n\n    def _check_bullet_alien_collisions(self):\n        \"\"\"Check whether any bullets have hit an alien.\"\"\"\n        collisions = pygame.sprite.groupcollide(\n                self.bullets, self.aliens, True, True)\n\n        # Award points for each alien destroyed.\n        if collisions:\n            for aliens in collisions.values():\n                self.stats.score += 10 * len(aliens)\n            self._prep_score()\n\n    def _create_alien(self):\n        \"\"\"Create an alien, if conditions are right.\"\"\"\n        if random() < self.settings.alien_frequency:\n            alien = Alien(self)\n            self.aliens.add(alien)\n\n    def _update_aliens(self):\n        \"\"\"Update alien positions, and look for collisions with ship.\"\"\"\n        self.aliens.update()\n\n        if pygame.sprite.spritecollideany(self.ship, self.aliens):\n            self._ship_hit()\n\n        # Look for aliens that have hit the left edge of the screen.\n        self._check_aliens_left_edge()\n\n    def _check_aliens_left_edge(self):\n        \"\"\"Respond to aliens that have hit left edge of the screen.\n        Treat this the same as the ship getting hit.\n        \"\"\"\n\n        for alien in self.aliens.sprites():\n            if alien.rect.left < 0:\n                self._ship_hit()\n                break\n\n    def _ship_hit(self):\n        \"\"\"Respond to an alien hitting the ship.\"\"\"\n        if self.stats.ships_left > 0:\n            # Decrement ships left.\n            self.stats.ships_left -= 1\n\n            # Get rid of any remaining aliens and bullets.\n            self.aliens.empty()\n            self.bullets.empty()\n\n            # Center the ship.\n            self.ship.center_ship()\n        else:\n            self.game_active = False\n\n    def _prep_score(self):\n        \"\"\"Turn the score into a rendered image.\"\"\"\n        score_str = f\"{self.stats.score:,}\"\n        self.score_image = self.score_font.render(\n                score_str, True, (0, 0, 0), self.settings.bg_color)\n\n        # Display the score at the top right of the screen.\n        self.score_rect = self.score_image.get_rect()\n        self.score_rect.right = self.screen.get_rect().right - 20\n        self.score_rect.top = 20\n\n    def _update_screen(self):\n        \"\"\"Update images on the screen, and flip to the new screen.\"\"\"\n        self.screen.fill(self.settings.bg_color)\n        self.ship.blitme()\n        for bullet in self.bullets.sprites():\n            bullet.draw_bullet()\n\n        self.aliens.draw(self.screen)\n\n        # Draw the score information.\n        if not hasattr(self, 'score_image'):\n            self.score_font = pygame.font.SysFont(None, 48)\n            self._prep_score()\n        self.screen.blit(self.score_image, self.score_rect)\n\n        # Draw the play button if the game is inactive.\n        if not self.game_active:\n            self.play_button.draw_button()\n\n        pygame.display.flip()\n\n\nif __name__ == '__main__':\n    # Make a game instance, and run the game.\n    ss_game = SidewaysShooter()\n    ss_game.run_game()\n","game_stats.py":"class GameStats:\n    \"\"\"Track statistics for the game.\"\"\"\n\n    def __init__(self, ss_game):\n        \"\"\"Initialize statistics.\"\"\"\n        self.settings = ss_game.settings\n        self.reset_stats()\n\n    def reset_stats(self):\n        \"\"\"Initialize statistics that can change during the game.\"\"\"\n        self.ships_left = self.settings.ship_limit\n        self.score = 0\n","button.py":"import pygame.font\n \nclass Button:\n \n    def __init__(self, ai_game, msg):\n        \"\"\"Initialize button attributes.\"\"\"\n        self.screen = ai_game.screen\n        self.screen_rect = self.screen.get_rect()\n        \n        # Set the dimensions and properties of the button.\n        self.width, self.height = 200, 50\n        self.button_color = (0, 135, 0)\n        self.text_color = (255, 255, 255)\n        self.font = pygame.font.SysFont(None, 48)\n        \n        # Build the button's rect object and center it.\n        self.rect = pygame.Rect(0, 0, self.width, self.height)\n        self.rect.center = self.screen_rect.center\n        \n        # The button message needs to be prepped only once.\n        self._prep_msg(msg)\n\n    def _prep_msg(self, msg):\n        \"\"\"Turn msg into a rendered image and center text on the button.\"\"\"\n        self.msg_image = self.font.render(msg, True, self.text_color,\n                self.button_color)\n        self.msg_image_rect = self.msg_image.get_rect()\n        self.msg_image_rect.center = self.rect.center\n\n    def _update_msg_position(self):\n        \"\"\"If the button has been moved, the text needs to be moved as well.\"\"\"\n        self.msg_image_rect.center = self.rect.center\n\n    def draw_button(self):\n        # Draw blank button and then draw message.\n        self.screen.fill(self.button_color, self.rect)\n        self.screen.blit(self.msg_image, self.msg_image_rect)","alien.py":"from random import randint\n\nimport pygame\nfrom pygame.sprite import Sprite\n \nclass Alien(Sprite):\n    \"\"\"A class to represent a single alien in the fleet.\"\"\"\n\n    def __init__(self, ss_game):\n        \"\"\"Initialize the alien and set its starting position.\"\"\"\n        super().__init__()\n        self.screen = ss_game.screen\n        self.settings = ss_game.settings\n\n        # Load the alien image and set its rect attribute.\n        self.image = pygame.image.load('images/alien_ship.png')\n        self.rect = self.image.get_rect()\n\n        # Start each new alien at a random position on the right side\n        #   of the screen.\n        self.rect.left = self.screen.get_rect().right\n        # The farthest down the screen we'll place the alien is the height\n        #   of the screen, minus the height of the alien.\n        alien_top_max = self.settings.screen_height - self.rect.height\n        self.rect.top = randint(0, alien_top_max)\n\n        # Store the alien's exact horizontal position.\n        self.x = float(self.rect.x)\n\n    def update(self):\n        \"\"\"Move the alien steadily to the left.\"\"\"\n        self.x -= self.settings.alien_speed\n        self.rect.x = self.x","bullet.py":"import pygame\nfrom pygame.sprite import Sprite\n \nclass Bullet(Sprite):\n    \"\"\"A class to manage bullets fired from the ship.\"\"\"\n\n    def __init__(self, ss_game):\n        \"\"\"Create a bullet object at the ship's current position.\"\"\"\n        super().__init__()\n        self.screen = ss_game.screen\n        self.settings = ss_game.settings\n        self.color = self.settings.bullet_color\n\n        # Create a bullet rect at (0, 0) and then set correct position.\n        self.rect = pygame.Rect(0, 0, self.settings.bullet_width,\n            self.settings.bullet_height)\n        self.rect.midright = ss_game.ship.rect.midright\n        \n        # Store the bullet's position as a decimal value.\n        self.x = float(self.rect.x)\n\n    def update(self):\n        \"\"\"Move the bullet across the screen.\"\"\"\n        # Update the decimal position of the bullet.\n        self.x += self.settings.bullet_speed\n        # Update the rect position.\n        self.rect.x = self.x\n\n    def draw_bullet(self):\n        \"\"\"Draw the bullet to the screen.\"\"\"\n        pygame.draw.rect(self.screen, self.color, self.rect)\n","settings.py":"class Settings:\n    \"\"\"A class to store all settings for Sideways Shooter.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game's settings.\"\"\"\n        # Screen settings\n        self.screen_width = 1200\n        self.screen_height = 800\n        self.bg_color = (230, 230, 230)\n\n        # Ship settings\n        self.ship_speed = 3.0\n        self.ship_limit = 3\n\n        # Bullet settings\n        self.bullet_speed = 6.0\n        self.bullet_width = 15\n        self.bullet_height = 3\n        self.bullet_color = (60, 60, 60)\n        self.bullets_allowed = 3\n\n        # Alien settings.\n        #  alien_frequency controls how often a new alien appear.s\n        #    Higher values -> more frequent aliens. Max = 1.0.\n        self.alien_frequency = 0.015\n        self.alien_speed = 6.0","ship.py":"import pygame\n \nclass Ship:\n    \"\"\"A class to manage the ship.\"\"\"\n \n    def __init__(self, ss_game):\n        \"\"\"Initialize the ship and set its starting position.\"\"\"\n        self.screen = ss_game.screen\n        self.settings = ss_game.settings\n        self.screen_rect = ss_game.screen.get_rect()\n\n        # Load the ship image and get its rect.\n        self.image = pygame.image.load('images/rocket_small.png')\n        self.rect = self.image.get_rect()\n\n        # Start each new ship at the center of the left side of the screen.\n        self.center_ship()\n\n        # Movement flags\n        self.moving_up = False\n        self.moving_down = False\n\n    def update(self):\n        \"\"\"Update the ship's position based on movement flags.\"\"\"\n        # Update the ship's y value, not the rect.\n        if self.moving_up and self.rect.top > 0:\n            self.y -= self.settings.ship_speed\n        if self.moving_down and self.rect.bottom < self.screen_rect.bottom:\n            self.y += self.settings.ship_speed\n\n        # Update rect object from self.y.\n        self.rect.y = self.y\n\n    def center_ship(self):\n        \"\"\"Center the ship on the left side of the screen.\"\"\"\n        self.rect.midleft = self.screen_rect.midleft\n\n        # Store a decimal value for the ship's vertical position.\n        self.y = float(self.rect.y)\n\n    def blitme(self):\n        \"\"\"Draw the ship at its current location.\"\"\"\n        self.screen.blit(self.image, self.rect)\n","images/rocket_small.png":{"b64":""},"images/alien_ship.png":{"b64":""},"images/GreenUFO_NoDmg.png":{"b64":""}}}};
